def _shared_big_club_groups(cur_tokens: set[str], prev_tokens: set[str]) -> int:
    shared = 0
    for group in BIG_CLUB_DUPLICATE_TOKEN_GROUPS:
        if cur_tokens & group and prev_tokens & group:
            shared += 1
