def _special_fact_quote_or_opinion(post: Post) -> bool:
    text = html.unescape("\n".join([_post_original_text(post), _post_original_text(post, quoted=True)]))
    if not _SPECIAL_QUOTE_ONLY_RE.search(text):
        return False
    # A quote that contains a concrete statistic/result remains a fact.
    concrete = bool(re.search(r"\b\d+(?:[.,]\d+)?\s*(?:%|goals?|assists?|matches?|minutes?|wins?|points?)\b|"
                              r"\d+(?:[.,]\d+)?\s*(?:אחוז|שערים|בישולים|משחקים|דקות|ניצחונות|נקודות)", text, re.I))
    return not concrete




