def _install_source_bypass(name: str, dedicated_value: Any = False, fabrizio_value: Any = False) -> None:
    previous = globals().get(name)
    if not callable(previous):
        return

    def wrapper(post: Post, *args: Any, _previous=previous, **kwargs: Any):
        if _is_dedicated_fact_post(post):
            return dedicated_value(post, *args, **kwargs) if callable(dedicated_value) else dedicated_value
        if is_fabrizio_open_transfer_report(post):
            return fabrizio_value(post, *args, **kwargs) if callable(fabrizio_value) else fabrizio_value
        return _previous(post, *args, **kwargs)

    wrapper.__name__ = name
    globals()[name] = wrapper


