def _retained_cluster_parallel_candidates_L18468(candidates: list[tuple[str, Post, float]]) -> list[tuple[str, Post, float]]:
    protected = [item for item in candidates if _is_dedicated_fact_post(item[1]) or is_fabrizio_open_transfer_report(item[1])]
    ordinary = [item for item in candidates if item not in protected]
    clustered = list(_previous_cluster_parallel_consolidated(ordinary) or [])
    combined = clustered + protected
    # Remove only absolute duplicate identities inside this in-memory batch.
    seen_ids: set[str] = set()
    result: list[tuple[str, Post, float]] = []
    for item in sorted(combined, key=lambda row: float(getattr(row[1], "published_ts", 0.0) or 0.0), reverse=True):
        post = item[1]
        identity = str(post.post_id or post.link or post_content_signature(post.username, post.text, post.quoted_text))
        if identity and identity in seen_ids:
            continue
        if identity:
            seen_ids.add(identity)
        result.append(item)
    return result
