def _remove_channel_signature_artifacts(text: str) -> str:
    value = str(text or "")
    value = re.sub(r"\[\s*נטו\s+ספורט\.?📝?\s*\]\(https?://t\.me/neto_sport\)\s*(?:\(https?://t\.me/neto_sport\))?", "", value, flags=re.I)
