def _attach_orphan_emoji_lines(text: str) -> str:
    lines = str(text or "").replace("\r", "").split("\n")
    result: list[str] = []
    pending_prefix: list[str] = []
    for raw in lines:
        line = raw.strip()
        if not line:
            if result and result[-1] != "":
                result.append("")
            continue
        if _EMOJI_ONLY_LINE_RE.fullmatch(line):
            # Before the first text it belongs to the next line; later it belongs to the prior text line.
            if not any(item for item in result if item):
                pending_prefix.append(line)
            else:
                index = len(result) - 1
                while index >= 0 and not result[index]:
                    index -= 1
                if index >= 0:
                    result[index] = result[index].rstrip() + " " + line
                else:
                    pending_prefix.append(line)
            continue
        if pending_prefix:
            line = "".join(pending_prefix) + line
            pending_prefix.clear()
        result.append(line)
    if pending_prefix and result:
        index = len(result) - 1
        while index >= 0 and not result[index]:
            index -= 1
        if index >= 0:
            result[index] = result[index].rstrip() + " " + "".join(pending_prefix)
    value = "\n".join(result)
    value = re.sub(r"\n{3,}", "\n\n", value)
    return value.strip()


def _sentence_units(text: str) -> list[str]:
    flat = re.sub(r"\s*\n+\s*", " ", str(text or "")).strip()
    if not flat:
        return []
    return [unit.strip() for unit in re.split(r"(?<=[.!?…])\s+(?=[\"“'‘(\[]?[א-תA-Za-z0-9🚨🇦-🇿])", flat) if unit.strip()]


def _merge_blocks_to_count(blocks: list[str], target: int) -> list[str]:
    blocks = [block.strip() for block in blocks if block.strip()]
    while len(blocks) > max(1, target):
        # Merge the shortest adjacent pair, preventing artificial one-sentence islands.
        index = min(range(len(blocks) - 1), key=lambda i: len(blocks[i]) + len(blocks[i + 1]))
        separator = "\n" if _LIST_LINE_RE.match(blocks[index]) or _LIST_LINE_RE.match(blocks[index + 1]) else " "
        blocks[index:index + 2] = [(blocks[index] + separator + blocks[index + 1]).strip()]
    return blocks


def _split_to_source_paragraph_count(source_blocks: list[str], translated: str) -> list[str]:
    units = _sentence_units(translated)
    target = len(source_blocks)
    if target <= 1 or len(units) < target:
        return [translated.strip()]
    source_weights = [max(1, count_content_words(block)) for block in source_blocks]
    total_weight = sum(source_weights)
    result: list[str] = []
    cursor = 0
    for index, weight in enumerate(source_weights):
        remaining_blocks = target - index
        remaining_units = len(units) - cursor
        if remaining_blocks == 1:
            take = remaining_units
        else:
            proportional = round(len(units) * weight / max(1, total_weight))
            take = max(1, min(proportional, remaining_units - (remaining_blocks - 1)))
        result.append(" ".join(units[cursor:cursor + take]).strip())
        cursor += take
    return [block for block in result if block]


def _compact_lists_and_spacing(text: str) -> str:
    lines = [line.strip() for line in str(text or "").replace("\r", "").split("\n")]
    result: list[str] = []
    for line in lines:
        if not line:
            if result and result[-1] != "":
                result.append("")
            continue
        current_is_list = bool(_LIST_LINE_RE.match(line))
        previous_nonempty = next((item for item in reversed(result) if item), "")
        previous_is_list = bool(_LIST_LINE_RE.match(previous_nonempty))
        if current_is_list and result and result[-1] == "":
            # No blank after a colon heading and no blank between list rows.
            if previous_is_list or previous_nonempty.endswith(":"):
                result.pop()
        if current_is_list and previous_is_list and result and result[-1] == "":
            result.pop()
        result.append(line)
    value = "\n".join(result)
    value = re.sub(r"(:)\n\n(?=" + _LIST_LINE_RE.pattern[1:-1] + r")", r"\1\n", value, flags=re.UNICODE)
    value = re.sub(r"\n{3,}", "\n\n", value)
    return value.strip()




def _safe_markdown_to_telegram_html(text: str) -> str:
    """Escape all text, converting only balanced **bold**/`code` markers."""
    value = str(text or "")
    tokens: list[str] = []

    def protect_bold(match: re.Match[str]) -> str:
        tokens.append("<b>" + html.escape(match.group(1), quote=False) + "</b>")
        return f"\x00B{len(tokens) - 1}\x00"

    def protect_code(match: re.Match[str]) -> str:
        tokens.append("<code>" + html.escape(match.group(1), quote=False) + "</code>")
        return f"\x00C{len(tokens) - 1}\x00"

    value = re.sub(r"\*\*([^*\n][^*]*?)\*\*", protect_bold, value)
    value = re.sub(r"`([^`\n]+)`", protect_code, value)
    value = html.escape(value, quote=False)
    for index, token in enumerate(tokens):
        value = value.replace(html.escape(f"\x00B{index}\x00"), token)
        value = value.replace(html.escape(f"\x00C{index}\x00"), token)
    # Unbalanced Markdown should never be visible as raw asterisks.
    value = value.replace("**", "")
    return value


