# Detect every clear generated equivalent, while avoiding ordinary phrases that
# merely contain the words "זה קורה" in an unrelated sentence.




def _source_logical_layout(source: str) -> tuple[list[str], list[str]]:
    """Return logical source segments and the real separators after each segment.

    Separators are either a single line break or a paragraph break. Only newlines
    actually present in the source text are used; Telegram/Desktop visual wrapping
    never enters the source string and therefore cannot create a new line here.
    """
    value = _attach_orphan_emoji_lines(str(source or "").replace("\r\n", "\n").replace("\r", "\n"))
    value = _DIRECTIONAL_ONLY_RE.sub("", value).strip()
    if not value:
        return [], []
    chunks = re.split(r"(\n+)", value)
    segments: list[str] = []
    separators: list[str] = []
    pending_separator = ""
    for chunk in chunks:
        if not chunk:
            continue
        if chunk.startswith("\n"):
            pending_separator = "\n\n" if len(chunk) >= 2 else "\n"
            continue
        clean = chunk.strip()
        if not clean:
            continue
        if segments:
            separators.append(pending_separator or "\n")
        segments.append(clean)
        pending_separator = ""
    return segments, separators


def _allocate_translation_to_source_segments(source_segments: list[str], translated: str) -> list[str]:
    """Conservative fallback when Gemini did not preserve all source separators."""
    target = len(source_segments)
    if target <= 1:
        return [re.sub(r"\s*\n+\s*", " ", translated).strip()]

    current = [part.strip() for part in re.split(r"\n+", translated) if part.strip()]
    if len(current) == target:
        return current

    units = _sentence_units(translated)
    if len(units) < target:
        # Do not fabricate sentence fragments unless the source itself has more
        # logical lines. Split the longest translated unit at a safe clause space.
        units = current or [translated.strip()]
        while len(units) < target:
            index = max(range(len(units)), key=lambda i: len(units[i]))
            candidate = units[index]
            split_points = [m.start() for m in re.finditer(r"\s+(?:[-–—;:]|אבל|אך|כאשר|בעוד|ו(?:הוא|היא|הם|המועדון))\s+", candidate)]
            if not split_points:
                words = candidate.split()
                if len(words) < 4:
                    break
                midpoint = len(words) // 2
                left, right = " ".join(words[:midpoint]), " ".join(words[midpoint:])
            else:
                point = min(split_points, key=lambda p: abs(p - len(candidate) / 2))
                left, right = candidate[:point].strip(), candidate[point:].strip()
            if not left or not right:
                break
            units[index:index + 1] = [left, right]

    if len(units) < target:
        return [translated.strip()]

    source_weights = [max(1, count_content_words(segment)) for segment in source_segments]
    total_weight = sum(source_weights)
    result: list[str] = []
    cursor = 0
    for idx, weight in enumerate(source_weights):
        remaining_segments = target - idx
        remaining_units = len(units) - cursor
        if remaining_segments == 1:
            take = remaining_units
        else:
            proportional = round(len(units) * weight / max(1, total_weight))
            take = max(1, min(proportional, remaining_units - (remaining_segments - 1)))
        result.append(" ".join(units[cursor:cursor + take]).strip())
        cursor += take
    return result


def _source_layout_is_artificial_sentence_rows(
    source_segments: list[str],
    source_separators: list[str],
) -> bool:
    """Detect RSS/translator sentence-per-line noise, not genuine X paragraphs.

    Some RSS mirrors turn an ordinary one-paragraph tweet into one physical row
    per sentence.  Those rows must not be reproduced in Telegram.  Genuine
    paragraphs (blank-line separators), lists, headings and quote blocks remain
    untouched.
    """
    if len(source_segments) < 3 or not source_separators:
        return False
    if any(separator == "\n\n" for separator in source_separators):
        return False
    if any(_LIST_LINE_RE.match(segment) for segment in source_segments):
        return False
    if any(segment.rstrip().endswith(":") for segment in source_segments[:-1]):
        return False

    # A run of ordinary prose sentences separated only by single newlines is the
    # exact shape produced by the problematic RSS/Google-Translate fallback.
    sentence_like = 0
    for segment in source_segments:
        plain = segment.strip().strip('"“”׳״')
        if not plain:
            continue
        if re.search(r"[.!?…][\"'”׳״)]?$", plain) or count_content_words(plain) >= 5:
            sentence_like += 1
    return sentence_like >= max(3, len(source_segments) - 1)


def _retained__restore_source_layout_L19279(post: Post, translated: str, quoted: bool = False) -> str:
    """Restore X/Twitter paragraphs while removing artificial sentence rows.

    Real blank-line paragraphs and lists are preserved.  When an RSS mirror or
    Google Translate split a normal paragraph into one sentence per line, the
    final Telegram body is joined back into natural continuous prose.
    """
    source = _post_original_text(post, quoted=quoted)
    value = _strip_internal_translation_output(translated)
    value = _remove_channel_signature_artifacts(value)
    value = _attach_orphan_emoji_lines(value)
    source_segments, source_separators = _source_logical_layout(source)

    source_is_single_prose_block = (
        len(source_segments) == 1
        or _source_layout_is_artificial_sentence_rows(source_segments, source_separators)
    )

    if not source_segments:
        value = re.sub(r"\n{3,}", "\n\n", value).strip()
    elif source_is_single_prose_block:
        # One ordinary X paragraph must stay one paragraph, even if Google
        # translated each sentence separately or an RSS mirror inserted rows.
        value = re.sub(r"\s*\n+\s*", " ", value).strip()
    else:
        translated_segments = _allocate_translation_to_source_segments(source_segments, value)
        if len(translated_segments) == len(source_segments):
            rebuilt = translated_segments[0]
            for separator, segment in zip(source_separators, translated_segments[1:]):
                rebuilt += separator + segment
            value = rebuilt
        else:
            # Last-resort conservative layout: never create more blocks than the
            # source, and never leave one sentence per paragraph.
            blocks = [part.strip() for part in re.split(r"\n{2,}", value) if part.strip()]
            value = "\n\n".join(_merge_blocks_to_count(blocks, len(source_segments))) if blocks else value

    value = _compact_lists_and_spacing(value)
    value = re.sub(r"(?:\.\s*){2,}(?=📝)", ".", value)
    value = re.sub(r"([!?])\s*\.\s*(?=📝)", r"\1", value)
    value = re.sub(r"([.!?])\s+(?=📝)", r"\1", value)
    value = _TRAILING_ATTRIBUTION_RE.sub("", value).rstrip()
    return re.sub(r"\n{3,}", "\n\n", value).strip()
