def is_ben_jacobs_concrete_report(post: Any) -> bool:
    """Recognize a substantive Ben Jacobs football-news update.

    The report may still be provisional (talks, bid, agreement in principle,
    rejection or deadline). It does not need to be 100% completed to be useful.
    """
    if not isinstance(post, Post):
        return False
    if str(getattr(post, "username", "") or "").strip().lstrip("@").casefold() != _BEN_JACOBS_USERNAME:
        return False
    source = html.unescape("\n".join([_post_original_text(post), _post_original_text(post, quoted=True)]))
    cleaned = clean_for_ai_translation(source)
    if count_content_words(cleaned) < 10:
        return False
    if not _BEN_JACOBS_CONCRETE_NEWS_RE.search(cleaned):
        return False
    # Require actual report substance: a strong mechanic/detail, a tracked club,
    # or multiple concrete transfer actions. This prevents generic opinion posts.
    mechanics = len(_BEN_JACOBS_CONCRETE_NEWS_RE.findall(cleaned))
    substantive = bool(
        _BEN_JACOBS_STRONG_DETAIL_RE.search(cleaned)
        or _CONCRETE_TRANSFER_REPORT_RE.search(cleaned)
        or _TRANSFER_NEWS_MECHANIC_RE.search(cleaned)
        or _matches_any(FINAL_OR_NEAR_FINAL_PATTERNS, cleaned)
        or _matches_any(FINAL_ONLY_STRICT_PATTERNS, cleaned)
        or _tracked_club_in_text(cleaned)
        or mechanics >= 2
    )
    return substantive


