def _special_source_block_lines(items: list[dict[str, Any]], source_name: str, limit: int = 10) -> list[str]:
    label = "עובדות כדורגל" if source_name == FOOTBALL_FACTLY_DEFAULT_ACTIVE_USERNAME else "אופטה"
    selected = [item for item in items if _special_diagnostic_item_source(item) == source_name][-limit:]
    lines = [f"{label} — {len(selected)} חסימות אחרונות שנמצאו:"]
    if not selected:
        lines.append("אין כרגע חסימות שמורות למקור הזה.")
        return lines
    for index, item in enumerate(selected, 1):
        ts = float(item.get("ts", 0.0) or 0.0)
        stamp = datetime.fromtimestamp(ts, tz=ZoneInfo(SHABBAT_TIMEZONE)).strftime("%d/%m %H:%M") if ts else "זמן לא ידוע"
        reason = hebrew_block_reason(str(item.get("reason", "") or item.get("raw_reason", "") or "סיבה לא ידועה"))
        preview = re.sub(r"\s+", " ", str(item.get("preview", "") or item.get("original_text", ""))).strip()
        link = str(item.get("link", "") or "")
        lines.append(f"{index}. {stamp} — {reason}")
        if preview:
            lines.append(f"   {trim(preview, 170)}")
        if link:
            lines.append(f"   {link}")
    return lines


