def _forward_origin_parts(message: dict[str, Any]) -> tuple[dict[str, Any], Any, Any, str]:
    origin = message.get("forward_origin") if isinstance(message.get("forward_origin"), dict) else {}
    origin_chat = origin.get("chat") if isinstance(origin.get("chat"), dict) else {}
    legacy_chat = message.get("forward_from_chat") if isinstance(message.get("forward_from_chat"), dict) else {}
    reply = message.get("reply_to_message") if isinstance(message.get("reply_to_message"), dict) else {}
    chat = origin_chat or legacy_chat or (reply.get("chat") if isinstance(reply.get("chat"), dict) else {}) or {}
    message_id = origin.get("message_id") or message.get("forward_from_message_id") or reply.get("message_id")
    chat_id = chat.get("id")
    body = str(message.get("text") or message.get("caption") or reply.get("text") or reply.get("caption") or "")
    return chat, chat_id, message_id, body




def identify_telegram_message_source(message: dict[str, Any]) -> dict[str, str]:
    chat, chat_id, message_id, body = _forward_origin_parts(message)
    matched = _lookup_original_sent_metadata(message)
    telegram_link = ""
    username = str(chat.get("username") or "").lstrip("@")
    if username and message_id:
        telegram_link = f"https://t.me/{username}/{message_id}"
    elif chat_id and message_id:
        internal = _telegram_internal_chat_id(chat_id)
        if internal:
            telegram_link = f"https://t.me/c/{internal}/{message_id}"

    if matched:
        source_username = str(matched.get("username") or matched.get("source") or "").strip().lstrip("@")
        source_label = _hebrew_account_label(source_username) if source_username else "מקור לא מזוהה"
        published = float(matched.get("published_ts", 0.0) or matched.get("ts", 0.0) or 0.0)
        try:
            date_text = datetime.fromtimestamp(published, ZoneInfo(SHABBAT_TIMEZONE)).strftime("%d/%m/%Y %H:%M")
        except Exception:
            date_text = "לא ידוע"
        return {
            "source": source_label,
            "source_username": source_username,
            "date": date_text,
            "link": str(matched.get("link") or ""),
            "telegram_link": telegram_link,
            "matched": "exact",
        }

    fallback = _previous_process_control_text_consolidated if False else None
    source_name = str(chat.get("title") or username or "מקור לא מזוהה")
    origin = message.get("forward_origin") if isinstance(message.get("forward_origin"), dict) else {}
    reply = message.get("reply_to_message") if isinstance(message.get("reply_to_message"), dict) else {}
    original_date = origin.get("date") or message.get("forward_date") or reply.get("date") or message.get("date")
    try:
        date_text = datetime.fromtimestamp(float(original_date), ZoneInfo(SHABBAT_TIMEZONE)).strftime("%d/%m/%Y %H:%M")
    except Exception:
        date_text = "לא ידוע"
    external = re.search(r"https?://(?:x\.com|twitter\.com)/[^\s<>]+", body)
    return {
        "source": source_name,
        "source_username": username,
        "date": date_text,
        "link": external.group(0).rstrip(".,)") if external else "",
        "telegram_link": telegram_link,
        "matched": "fallback",
    }


