def _enforce_here_we_go_from_source(post: Post, translated: str) -> str:
    source = _post_original_text(_ensure_post_original_structure(post), quoted=False)
    source_has = bool(_HERE_WE_GO_SOURCE_RE.search(source))
    value = str(translated or "")
    if source_has:
        found = False

        def keep_once(_match: re.Match[str]) -> str:
            nonlocal found
            if found:
                return ""
            found = True
            return "HERE WE GO"

        value = _HERE_WE_GO_OUTPUT_RE.sub(keep_once, value)
        if not found:
            value = value.rstrip(" .,!;:") + ", HERE WE GO!"
    else:
        value = _HERE_WE_GO_OUTPUT_RE.sub("", value)
    value = re.sub(r"[ \t]+([,.;!?])", r"\1", value)
    value = re.sub(r"([,;])\s*([.!?])", r"\2", value)
    value = re.sub(r"[ \t]{2,}", " ", value)
    value = re.sub(r"(?m)^\s*[,;:.-]+\s*$", "", value)
    return re.sub(r"\n{3,}", "\n\n", value).strip(" \t,;:-")


_previous_strict_confirmation_person_keys = _strict_confirmation_person_keys


def _strict_confirmation_person_keys(text: str, signature: dict[str, Any]) -> set[str]:
    keys = _previous_strict_confirmation_person_keys(text, signature)
    action_noise = {
        "completed", "complete", "agreed", "agree", "talks", "negotiations", "advanced",
        "deal", "official", "confirmed", "medical", "documents", "joining", "signed",
        "הושלם", "סוכם", "הסכים", "מגעים", "שיחות", "מתקדם", "רשמי", "חתם", "מצטרף",
    }
    cleaned: set[str] = set()
    for key in keys:
        prefix, _, phrase = key.partition(":")
        words = [word for word in phrase.split() if word not in action_noise]
        if prefix == "player" and words:
            cleaned.add(key)
        elif prefix == "name" and len(words) >= 2:
            cleaned.add("name:" + " ".join(words))
    return cleaned


# Search the unpruned reply-target rows first so forwarding an older channel post
# still resolves its original writer and X link when the message ID is available.
def _lookup_original_sent_metadata(message: dict[str, Any]) -> dict[str, Any] | None:
    _chat, origin_chat_id, origin_message_id, body = _forward_origin_parts(message)
    try:
        state = load_state()
    except Exception:
        state = {}
    raw = state.get(BOT_SENT_REPLY_STATE_KEY, []) if isinstance(state, dict) else []
    candidates = [item for item in (raw if isinstance(raw, list) else []) if isinstance(item, dict)]
    for item in reversed(candidates):
        mids = item.get("message_ids", {})
        if not isinstance(mids, dict):
            continue
        for stored_chat, stored_mid in mids.items():
            if str(stored_mid) != str(origin_message_id):
                continue
            if origin_chat_id and str(stored_chat) != str(origin_chat_id):
                continue
            return item
    normalized_body = html_message_to_plain_text(body).strip()
    if normalized_body:
        best_score = 0.0
        best_item: dict[str, Any] | None = None
        for item in reversed(candidates[-500:]):
            previous = str(item.get("rendered") or item.get("ai_text") or item.get("original_text") or item.get("preview") or "")
            score = memory_similarity(normalized_body, previous)
            if score > best_score:
                best_score, best_item = score, item
        if best_score >= 0.82:
            return best_item
    return None



# Preserve paragraph breaks when removing the hidden FootballFactly/Opta heading.
def strip_football_factly_author_heading(message: Any) -> str:
    text = str(message or "")
    heading = r"(?:עובדות\s+כדורגל|FootballFactly|@FootballFactly|אופטה(?:\s+ג[׳']?ו)?|OptaJoe|@OptaJoe)"
    # Remove only a real leading source-heading row. Never collapse generic
    # whitespace: \s{2,} also matches newlines and previously flattened the exact
    # X paragraph layout during manual/forced preparation.
    text = re.sub(
        rf"^\s*(?:<b>)?\s*{heading}\s*(?:</b>)?\s*[:：\-–—]?\s*(?:<br\s*/?>|\r?\n)+",
        "",
        text,
        count=1,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        rf"^\s*(?:<b>)?\s*{heading}\s*(?:</b>)?\s*[:：\-–—]?\s*",
        "",
        text,
        count=1,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()



