def _acceptance_remove_promotional_tail(text: str) -> str:
    raw = str(text or "")
    blocks = [block.strip() for block in re.split(r"\n{2,}", raw) if block.strip()]
    kept: list[str] = []
    for block in blocks:
        first = block.splitlines()[0].strip()
        has_promo_emoji = bool(re.match(r"^[🎥🎙🎤🎬📺▶️]", first))
        has_promo_words = bool(_ACCEPTANCE_PROMO_TAIL_RE.search(first))
        has_link = bool(re.search(r"https?://|www\.", block, re.IGNORECASE))
        if kept and (has_promo_emoji or has_promo_words) and (has_link or re.search(r"פודקאסט|ראיון|סרטון|video|podcast|interview", block, re.IGNORECASE)):
            break
        kept.append(block)
    value = "\n\n".join(kept).strip()
    # Earlier legacy layout code may flatten the blank line. Remove an inline
    # promotional tail only when it starts with a dedicated media/podcast emoji.
    value = re.sub(
        r"\s+[🎥🎙🎤🎬📺▶️]+\s*(?:צפו|לצפייה|האזינו|להאזנה|watch|listen|view|full\s+(?:video|interview|podcast|episode))[\s\S]*$",
        "",
        value,
        flags=re.IGNORECASE,
    )
    return value.strip()


def _acceptance_remove_source_credits(text: str) -> str:
    lines = str(text or "").splitlines()
    cleaned: list[str] = []
    for line in lines:
        if _ACCEPTANCE_SKY_CREDIT_RE.match(line):
            continue
        cleaned.append(line)
    value = "\n".join(cleaned)
    value = re.sub(
        r"\s+(?:לפי\s+)?(?:Sky\s*Sport(?:s)?\s*(?:Germany|DE)|Sky\s*Germany|SkySportDE|סקיי\s*ספורט(?:ס)?\s*גרמניה|סקיי\s*גרמניה)\s*(?:🇩🇪|[#@][\w.]+)?\s*$",
        "",
        value,
        flags=re.IGNORECASE,
    )
    value = re.sub(r"(?:\s+לפי)\s*([.!?,])", r"\1", value)
    value = re.sub(r"(?:\s+לפי)\s*$", "", value)
    return value.strip()


def _acceptance_remove_trailing_team_tag(text: str) -> str:
    """Remove a repeated club label only when it is visibly detached.

    A club name that completes the actual sentence (for example "עבר לליל")
    must remain.  Removal is allowed only after terminal punctuation or on a
    separate final line, and only when the same club is already present earlier.
    """
    value = str(text or "").strip()
    if not value:
        return value

    aliases: set[str] = set()
    for item in TEAM_CATALOG.values():
        if not isinstance(item, dict):
            continue
        aliases.add(str(item.get("name") or "").strip())
        aliases.update(str(x or "").strip() for x in (item.get("aliases") or []))
    for key, translated in TEAM_REPLACEMENTS.items():
        aliases.add(str(key or "").strip())
        aliases.add(str(translated or "").strip())
    aliases = {alias for alias in aliases if alias}
    if not aliases:
        return value

    def norm(candidate: str) -> str:
        return re.sub(r"[^A-Za-zא-ת0-9]+", " ", str(candidate or "")).strip().casefold()

    norm_to_alias = {norm(alias): alias for alias in aliases if norm(alias)}
    terminal_re = re.compile(r"[.!?…][\"'״׳)\]]*\s*$")

    # Final isolated line (single newline is enough), only after a completed
    # sentence.  Do not remove an ordinary last line that is part of a sentence.
    lines = value.splitlines()
    nonempty_indexes = [i for i, line in enumerate(lines) if line.strip()]
    if len(nonempty_indexes) >= 2:
        last_i = nonempty_indexes[-1]
        previous_text = "\n".join(lines[:last_i]).rstrip()
        last_norm = norm(lines[last_i].strip().strip(".!?…"))
        alias = norm_to_alias.get(last_norm)
        if alias and terminal_re.search(previous_text):
            earlier_norm = norm(previous_text)
            translated_alias = str(TEAM_REPLACEMENTS.get(alias, "") or "")
            if norm(alias) in earlier_norm or (translated_alias and norm(translated_alias) in earlier_norm):
                return "\n".join(lines[:last_i]).rstrip()

    # Flattened RSS may leave the tag on the same line.  Require punctuation
    # immediately before the detached tag; never strip a club that is simply the
    # grammatical end of the sentence.
    for alias in sorted(aliases, key=len, reverse=True):
        pattern = re.compile(
            rf"(?s)^(?P<body>.*?[.!?…][\"'״׳)\]]*)\s+(?:[#@])?{re.escape(alias)}[.!?…]?\s*$",
            re.IGNORECASE,
        )
        match = pattern.match(value)
        if not match:
            continue
        body = match.group("body").rstrip()
        earlier_norm = norm(body)
        translated_alias = str(TEAM_REPLACEMENTS.get(alias, alias) or alias)
        if norm(alias) in earlier_norm or norm(translated_alias) in earlier_norm:
            return body
    return value

def _acceptance_restore_flat_statistics(post: Post, text: str) -> str:
    if bool(getattr(post, "exact_source_structure", False)):
        return text
    value = str(text or "").strip()
    if "\n•" in value or "\n-" in value:
        return value
    matches = list(re.finditer(r"([^()\n:;]{3,90}?)\s*\((\d[\d.,%]*)\)", value))
    if len(matches) < 3:
        return value
    first_start = matches[0].start()
    prefix = value[:first_start].strip(" ,;:-")
    # Keep a real lead sentence ending in a colon when possible.
    colon_index = value.rfind(":", 0, first_start + 1)
    if colon_index >= 0:
        prefix = value[:colon_index].strip() + ":"
    bullets: list[str] = []
    for match in matches[:15]:
        label = re.sub(r"\s+", " ", match.group(1)).strip(" ,;:-")
        label = re.sub(r"^(?:ו|and)\s+", "", label, flags=re.IGNORECASE)
        number = match.group(2).strip()
        if len(label.split()) > 12 or len(label) < 3:
            return value
        bullets.append(f"• {label} — {number}")
    if len(bullets) < 3:
        return value
    return (prefix + "\n\n" + "\n".join(bullets)).strip()




