def _final_is_detached_source_metadata(line: str) -> bool:
    value = html.unescape(str(line or "")).strip()
    if not value or len(value) > 240 or re.search(r"\d{2,}", value):
        return False
    mentions = _FINAL_METADATA_MENTION_RE.findall(value)
