# Explicit source aliases are applied before/after translation.  In addition,
# the generic prefix stripper below acts only when the Hebrew club name is a
# known display name from the existing team database, so ordinary initials or
# player names are never altered.
TEAM_REPLACEMENTS.update({
    "RC Strasbourg": "שטרסבורג",
    "Racing Club de Strasbourg": "שטרסבורג",
    "RC Strasbourg Alsace": "שטרסבורג",
    "Strasbourg Alsace": "שטרסבורג",
    "AZ Alkmaar": "אלקמאר",
    "Alkmaar Zaanstreek": "אלקמאר",
})

_REQUESTED_CLUB_PREFIXES: tuple[str, ...] = (
    "RCD", "RSC", "KRC", "LOSC", "OGC", "TSG", "VFB", "VFL",
    "AFC", "AC", "AS", "AZ", "BK", "CA", "CD", "CF", "CR", "EC",
    "FC", "FK", "IF", "IK", "NK", "RC", "RB", "SC", "SK", "SL",
    "SS", "SV", "UD", "US",
)


def _requested_known_hebrew_club_names() -> list[str]:
    names: set[str] = set()
    catalog = globals().get("TEAM_CATALOG", {})
    if isinstance(catalog, dict):
        for row in catalog.values():
            if not isinstance(row, dict):
                continue
            name = str(row.get("name") or "").strip()
            if name and re.search(r"[א-ת]", name):
                names.add(name)
    for value in TEAM_REPLACEMENTS.values():
        name = str(value or "").strip()
        if name and re.search(r"[א-ת]", name):
            names.add(name)
    names.update({"שטרסבורג", "אלקמאר", "רומא"})
    return sorted(names, key=len, reverse=True)


def _requested_normalize_club_display_names(value: Any) -> str:
    text = str(value or "")
    if not text:
        return text
    # First use the complete known alias dictionary, longest aliases first.
    for alias, replacement in sorted(TEAM_REPLACEMENTS.items(), key=lambda item: len(str(item[0])), reverse=True):
        alias_text = str(alias or "").strip()
        replacement_text = str(replacement or "").strip()
        if not alias_text or not replacement_text:
            continue
        # Hebrew short aliases such as "ריבר" -> "ריבר פלייט" can already be
        # part of the canonical display name. The established Hebrew polish layer
        # handles those aliases; this pass is only for Latin/source club names.
        if not re.search(r"[A-Za-z]", alias_text):
            continue
        text = re.sub(
            rf"(?<![A-Za-z0-9א-ת]){re.escape(alias_text)}(?![A-Za-z0-9א-ת])",
            replacement_text,
            text,
            flags=re.IGNORECASE,
        )
    club_names = _requested_known_hebrew_club_names()
    if club_names:
        prefix = "|".join(re.escape(item) for item in _REQUESTED_CLUB_PREFIXES)
        clubs = "|".join(re.escape(item) for item in club_names)
        # Supports forms such as RC שטרסבורג, AZ אלקמאר, AS רומא and
        # Hebrew prepositions attached to the Latin prefix: ל-RC שטרסבורג.
        text = re.sub(
            rf"(?iu)(?P<prep>(?<![א-ת])[בלמכהו]-?)?(?:{prefix})[.\s\-־]+(?P<club>{clubs})(?![A-Za-z0-9א-ת])",
            lambda match: (match.group("prep") or "") + match.group("club"),
            text,
        )
    text = re.sub(r"(?iu)\b(?:AS|A\.S\.)\s+רומא\b", "רומא", text)
    # Hebrew prepositions conventionally attach directly to the normalized club
    # name: ל-RC שטרסבורג -> לשטרסבורג.
    club_names = _requested_known_hebrew_club_names()
    if club_names:
        clubs = "|".join(re.escape(item) for item in club_names)
        text = re.sub(
            rf"(?iu)(?<![א-ת])(?P<prep>[בלמכהו])-+(?P<club>{clubs})(?![A-Za-z0-9א-ת])",
            lambda match: match.group("prep") + match.group("club"),
            text,
        )
    return re.sub(r"[ \t]{2,}", " ", text)


