# Exact source-text reservation closes the remaining race where the same content
# arrives from two automatic discovery paths with different mirror IDs.
_REQUESTED_EXACT_TEXT_LOCK = RLock()
_REQUESTED_EXACT_TEXT_INFLIGHT: dict[str, float] = {}
_REQUESTED_EXACT_TEXT_SENT: dict[str, float] = {}


def _requested_exact_text_fingerprint(post: Post) -> str:
    text = _final_repost_normalize(_final_source_text(post))
    username = str(getattr(post, "username", "") or "").strip().lstrip("@").casefold()
    return hashlib.sha256((username + "\n" + text).encode("utf-8", errors="ignore")).hexdigest() if text else ""




_PRE_REQUESTED_EXACT_SEND_POST = send_post


def send_post(post: Post, reply_message_ids: dict[str, int] | None = None, state: dict[str, Any] | None = None) -> dict[str, Any]:
    fingerprint = _requested_exact_text_fingerprint(post)
    now = time.time()
    if fingerprint:
        with _REQUESTED_EXACT_TEXT_LOCK:
            for mapping in (_REQUESTED_EXACT_TEXT_INFLIGHT, _REQUESTED_EXACT_TEXT_SENT):
                for key, timestamp in list(mapping.items()):
                    if now - timestamp > 48 * 60 * 60:
                        mapping.pop(key, None)
            if fingerprint in _REQUESTED_EXACT_TEXT_INFLIGHT or fingerprint in _REQUESTED_EXACT_TEXT_SENT:
                return {"sent": False, "mode": "pre_send_blocked:requested_exact_text_duplicate", "total_seconds": 0.0}
            if _requested_exact_text_already_in_memory(post, fingerprint):
                _REQUESTED_EXACT_TEXT_SENT[fingerprint] = now
                return {"sent": False, "mode": "pre_send_blocked:requested_exact_text_duplicate", "total_seconds": 0.0}
            _REQUESTED_EXACT_TEXT_INFLIGHT[fingerprint] = now
    result: dict[str, Any] | None = None
    try:
        result = _PRE_REQUESTED_EXACT_SEND_POST(post, reply_message_ids=reply_message_ids, state=state)
        return result
    finally:
        if fingerprint:
            with _REQUESTED_EXACT_TEXT_LOCK:
                _REQUESTED_EXACT_TEXT_INFLIGHT.pop(fingerprint, None)
                if isinstance(result, dict) and bool(result.get("sent")):
                    _REQUESTED_EXACT_TEXT_SENT[fingerprint] = time.time()

