# ---------------------------------------------------------------------------
# 5) Faster control buttons. Process each update immediately and persist the
#    Telegram offset only once after the batch, instead of writing a JSON file
#    before every click. Long polling still returns instantly when a click arrives.
# ---------------------------------------------------------------------------
CONTROL_POLL_SECONDS = min(float(CONTROL_POLL_SECONDS), 0.05)


def control_loop() -> None:
    if not CONTROL_CHAT_ID:
        return
    delete_control_webhook_if_needed()
    offset = control_saved_offset()
    last_conflict_cleanup = 0.0
    if CONTROL_SEND_PANEL_ON_STARTUP:
        try:
            send_quick_control_panel(force_new=True)
        except Exception as exc:
            logging.debug("לוח שליטה: אתחול נכשל: %s", exc)
    else:
        try:
            ensure_control_panel_once_if_requested()
        except Exception as exc:
            logging.debug("לוח שליטה: יצירת לוח חסר נכשלה: %s", exc)

    while True:
        try:
            response = telegram_api(
                "getUpdates",
                {
                    "offset": offset,
                    "timeout": int(os.environ.get("CONTROL_GETUPDATES_TIMEOUT", "20")),
                    "allowed_updates": [
                        "callback_query",
                        "message",
                        "edited_message",
                        "channel_post",
                        "edited_channel_post",
                    ],
                },
            )
            updates = response.get("result", []) or []
            batch_offset = offset
            for update in updates:
                batch_offset = max(batch_offset, int(update.get("update_id", 0)) + 1)
                # Handle the click before any persistent disk write.
                process_control_update(update)
                process_control_text_update(update)
                process_channel_post_update(update)
            if batch_offset != offset:
                offset = batch_offset
                save_control_state(control_update_offset=offset)
        except Exception as exc:
            if is_getupdates_conflict(exc):
                now = time.time()
                if now - last_conflict_cleanup > 30:
                    last_conflict_cleanup = now
                    try:
                        telegram_api("deleteWebhook", {"drop_pending_updates": True}, max_attempts=1)
                    except Exception as cleanup_exc:
                        logging.warning("⚠️ לוח שליטה: ניקוי התנגשות נכשל: %s", cleanup_exc)
                time.sleep(CONTROL_POLL_SECONDS)
                continue
            logging.warning("⚠️ לוח שליטה: האזנה לכפתורים נכשלה: %s", exc)
            time.sleep(CONTROL_POLL_SECONDS)

# ====== END USER CONSOLIDATED FIX V2 ======

# ====== USER HOTFIX V3: KEEP SUCCESSFUL ALBUM WHEN TELEGRAM CONFIRMS NO CHANGE (2026-08-03) ======
# Telegram may apply editMessageReplyMarkup and then let the HTTP response time out.
# Repeating the same edit then returns HTTP 400 "message is not modified", which is
# positive confirmation that the requested keyboard is already attached.  The old
# code treated that confirmation as a total album failure and deleted the successful
# media group.  This layer makes the keyboard step idempotent and never destroys a
# successfully uploaded album merely because the post-upload edit response was late.



def _user_v3_message_not_modified(exc: BaseException | str) -> bool:
    value = str(exc or "").casefold()
    return "message is not modified" in value or "message_not_modified" in value


def _user_v3_attach_album_keyboard(
    chat_id: str,
    message_id: int,
    caption: str,
    markup: dict[str, Any],
) -> bool:
    """Attach the keyboard idempotently to the captioned album item.

    A timeout is ambiguous: Telegram may already have applied the edit.  Repeating
    the exact same edit is safe; a subsequent "message is not modified" means the
    desired keyboard is already present and therefore counts as success.
    """
    payload = {
        "chat_id": chat_id,
        "message_id": int(message_id),
        "reply_markup": markup,
    }
    timeout = max(4.0, float(TELEGRAM_BUTTON_FAST_TIMEOUT_SECONDS))
    first_error: Exception | None = None

    for attempt in range(2):
        try:
            telegram_api(
                "editMessageReplyMarkup",
                payload,
                max_attempts=1,
                timeout=timeout,
            )
            return True
        except Exception as exc:
            if _user_v3_message_not_modified(exc):
                logging.info(
                    "Album keyboard is already attached; Telegram returned message is not modified. message_id=%s",
                    message_id,
                )
                return True
            if first_error is None:
                first_error = exc
            # The second identical request resolves the common case where Telegram
            # performed the first edit but its HTTP response arrived too late.
            if attempt == 0:
                continue

    # Compatibility fallback for Bot API deployments that only accept the keyboard
    # when the existing caption is supplied with it.  This is also idempotent.
    try:
        telegram_api(
            "editMessageCaption",
            {
                "chat_id": chat_id,
                "message_id": int(message_id),
                "caption": caption,
                "parse_mode": "HTML",
                "reply_markup": markup,
            },
            max_attempts=1,
            timeout=timeout,
        )
        return True
    except Exception as exc:
        if _user_v3_message_not_modified(exc):
            logging.info(
                "Album caption/keyboard was already updated; treating no-change response as success. message_id=%s",
                message_id,
            )
            return True
        logging.warning(
            "Album uploaded successfully, but inline keyboard attachment failed; album is kept. "
            "message_id=%s first_error=%s final_error=%s",
            message_id,
            short_error(first_error, 350) if first_error else "",
            short_error(exc, 350),
        )
        return False



# ====== END USER HOTFIX V3 ======


# ====== USER ROOT FIX V4: RELIABLE ALBUM ACTIONS / STRUCTURAL LAYOUT / CENTREGOALS NEWS (2026-08-03) ======
# This final override fixes the root causes without changing RSS endpoints,
# persistent filenames/keys, translation models, account state, or sent history.


# ---------------------------------------------------------------------------
# 1) RSS mirrors may insert physical line rows for visual wrapping. A physical
#    row is not automatically an X paragraph. Collapse single prose rows and
#    merge a blank boundary only when the preceding clause is visibly unfinished.
#    Genuine completed paragraphs, headings and lists remain separate.
# ---------------------------------------------------------------------------
_USER_V4_HTML_TAG_RE = re.compile(r"(?is)<[^>]+>")
_USER_V4_INVISIBLE_RE = re.compile(r"[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]")
_USER_V4_TRAILING_VISUAL_RE = re.compile(
    r"(?s)(?:(?:[\U0001F1E6-\U0001F1FF]{2})|[\U0001F300-\U0001FAFF]|[\u2600-\u27BF]|"
    r"[\u200d\ufe0e\ufe0f\s])+$"
)


def _user_v4_plain_for_boundary(value: Any) -> str:
    probe = html.unescape(_USER_V4_HTML_TAG_RE.sub("", str(value or "")))
    probe = _USER_V4_INVISIBLE_RE.sub("", probe).strip()
    # Remove only trailing visual emoji/variation characters. Punctuation before
    # an emoji remains available for the completed-sentence check.
    probe = _USER_V4_TRAILING_VISUAL_RE.sub("", probe).rstrip()
    return probe


def _user_v4_is_list_line(value: Any) -> bool:
    line = _user_v4_plain_for_boundary(value).strip()
    if not line:
        return False
    try:
        if _LIST_LINE_RE.match(line):
            return True
    except Exception:
        pass
    return bool(re.match(r"^(?:[•▪▫◦‣⁃*+-]|\d+[.)]|[A-Za-zא-ת][.)])\s+", line))


def _user_v4_paragraph_is_complete(value: Any) -> bool:
    probe = _user_v4_plain_for_boundary(value)
    return bool(re.search(r"[.!?…][\"'”’״׳)\]]*$", probe))


def _user_v4_collapse_physical_rows(block: Any) -> str:
    lines = [line.strip() for line in str(block or "").splitlines() if line.strip()]
    if len(lines) <= 1:
        return lines[0] if lines else ""
    result: list[str] = []
    for line in lines:
        if not result:
            result.append(line)
            continue
        previous = result[-1]
        current_is_list = _user_v4_is_list_line(line)
        previous_is_list = _user_v4_is_list_line(previous)
        if current_is_list or previous_is_list:
            result.append(line)
        else:
            result[-1] = previous.rstrip() + " " + line.lstrip()
    return "\n".join(result)




