_retained__finalize_outgoing_message_only_L49923.__name__ = _retained__finalize_outgoing_message_only_L49923.__qualname__ = '_finalize_outgoing_message_only'
_finalize_outgoing_message_only = _retained__finalize_outgoing_message_only_L49923

# ====== END FINAL LEADING ENTITY / ADJACENT CLUB DUPLICATION FIX V17 ======


# ====== FINAL EMOJI-LED RTL PARAGRAPH MARK FIX V18 (2026-08-03) ======
# Narrow display-only correction. The media-aware writer renderer strips leading
# invisible characters while removing duplicate writer prefixes. When the first
# body paragraph starts with an emoji, that can remove the RLM inserted by rtl().
# Telegram Desktop then treats an L-direction emoji such as 🆕 as the paragraph
# opener and displays the whole leading emoji cluster on the left. Restore exactly
# one RLM only on emoji-led lines that contain Hebrew. No wording, spacing, filters,
# RSS behavior, buttons, media, signatures or other message settings are changed.

BOT_BUILD_ID = "winner-emoji-led-rtl-mark-only-2026-08-03-v18"

_V18_BIDI_INVISIBLE_CHARS = "\u200e\u200f\u202a\u202b\u202c\u202d\u202e\u2066\u2067\u2068\u2069\ufeff"
_V18_LEADING_HTML_TAG_RE = re.compile(
    r"^(?:\s*<(?:b|strong|i|em|u|s|span|a|tg-emoji)(?:\s+[^>]*)?>\s*)+",
    re.IGNORECASE,
)


def _v18_visible_line(line: Any) -> str:
    value = html.unescape(re.sub(r"<[^>]+>", "", str(line or "")))
    return value


def _v18_line_already_has_rtl_anchor(line: str) -> bool:
    """Return True when the first visible text position is already RTL-anchored."""
    raw = str(line or "")
    # A mark before the first HTML tag is authoritative.
    stripped_raw = raw.lstrip(" \t")
    if stripped_raw.startswith(RTL_MARK):
        return True

    # A mark inside leading formatting tags is also authoritative, e.g.
    # <b>\u200fReporter:</b>.
    visible = _v18_visible_line(raw).lstrip(" \t")
    return visible.startswith(RTL_MARK)


def _v18_is_emoji_led_hebrew_line(line: str) -> bool:
    visible = _v18_visible_line(line)
    probe = visible.lstrip(" \t" + _V18_BIDI_INVISIBLE_CHARS)
    if not probe or not re.search(r"[\u0590-\u05FF]", probe):
        return False

    # The first real item must be an emoji/flag/symbol cluster. Use the bot's
    # existing emoji catalog so this stays consistent with translation cleanup.
    if TAG_FLAG_RE.match(probe):
        return True
    return bool(EMOJI_RE.match(probe))


def _v18_restore_emoji_led_rtl_marks(message: Any) -> str:
    value = str(message or "")
    if not value:
        return value

    lines = value.split("\n")
    changed = False
    for index, line in enumerate(lines):
        if not line.strip():
            continue
        if _v18_line_already_has_rtl_anchor(line):
            continue
        if not _v18_is_emoji_led_hebrew_line(line):
            continue
        # Place the mark before any HTML/text. This changes no visible character
        # and makes Telegram determine the paragraph as RTL before reading 🆕 or
        # any other emoji whose bidi class can otherwise select LTR.
        lines[index] = RTL_MARK + line
        changed = True

    return "\n".join(lines) if changed else value


# Restore the mark immediately after all writer-header/layout wrappers.
_V18_PRE_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _V18_PRE_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    return _v18_restore_emoji_led_rtl_marks(rendered)


# Repeat only this invisible display correction at the absolute outgoing boundary
# for cached translations, forced quiet-channel preparation and legacy candidates.
_V18_PRE_FINALIZE_OUTGOING = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    return _v18_restore_emoji_led_rtl_marks(_V18_PRE_FINALIZE_OUTGOING(message))

# ====== END FINAL EMOJI-LED RTL PARAGRAPH MARK FIX V18 ======


# ====== V20 REQUESTED RELIABILITY / FAST DISCOVERY / FORMAT / LOGO AUDIT ======
