# ---------------------------------------------------------------------------
# 3) Duplicate/burst history is built only from messages that were actually sent
#    to the Neto Sport main channel. Quiet previews, blocked posts and pending
#    candidates are excluded.
# ---------------------------------------------------------------------------

def _v20_is_actual_main_channel_row(item: dict[str, Any], *, source_key: str = "") -> bool:
    if not isinstance(item, dict) or bool(item.get("pending", False)):
        return False
    source = str(item.get("username") or item.get("source") or item.get("sent_via") or "").casefold()
    if source_key in {"recent", "last_sent", "reply_targets", "durable"}:
        return True
    if source_key == "channel":
        accepted = {
            "bot_sent", "manual_force", "manual_force_live_edited",
            "manual_telegram_immediate_copy", "manual_telegram_copy_combined",
            "manual_force_edited", "button_or_auto", "button_or_auto_strict_media",
        }
        if source in accepted:
            return True
        message_ids = item.get("message_ids")
        if isinstance(message_ids, dict):
            target_ids = {str(value) for value in TELEGRAM_CHAT_IDS}
            if any(str(chat_id) in target_ids for chat_id in message_ids):
                return True
        return False
    return False


def _v20_recent_duplicate_rows(state: dict[str, Any]) -> list[dict[str, Any]]:
    now = time.time()
    collected: list[tuple[dict[str, Any], str]] = []
    if isinstance(state, dict):
        key_specs = [
            (str(globals().get("RECENT_NEWS_STATE_KEY", "__recent_news_events__")), "recent"),
            ("recent_news_events", "recent"),
            (str(globals().get("CHANNEL_RECENT_NEWS_STATE_KEY", "__channel_recent_news_events__")), "channel"),
            ("channel_recent_news_events", "channel"),
            ("last_sent_posts", "last_sent"),
            (str(globals().get("BOT_SENT_REPLY_TARGETS_STATE_KEY", "bot_sent_reply_targets")), "reply_targets"),
            ("bot_sent_reply_targets", "reply_targets"),
        ]
        seen_keys: set[str] = set()
        for key, kind in key_specs:
            if not key or key in seen_keys:
                continue
            seen_keys.add(key)
            values = state.get(key, [])
            if isinstance(values, list):
                collected.extend((item, kind) for item in values if isinstance(item, dict))
    collected.extend((item, "durable") for item in _v9_durable_duplicate_rows() if isinstance(item, dict))

    unique: dict[str, dict[str, Any]] = {}
    for item, kind in collected:
        if not _v20_is_actual_main_channel_row(item, source_key=kind):
            continue
        try:
            timestamp = float(item.get("ts") or item.get("sent_at") or item.get("created_at") or 0.0)
        except Exception:
            timestamp = 0.0
        if timestamp and now - timestamp > _V9_DUPLICATE_WINDOW_SECONDS:
            continue
        text = _v9_item_text(item)
        if not text:
            continue
        identity = str(item.get("post_id") or item.get("link") or item.get("id") or "").strip()
        if not identity:
            identity = hashlib.sha1(_v9_duplicate_plain_text(text).encode("utf-8", errors="ignore")).hexdigest()
        unique[identity] = item
    return list(unique.values())[-_V9_DUPLICATE_MAX_ROWS:]


_v9_recent_duplicate_rows = _v20_recent_duplicate_rows

# ---------------------------------------------------------------------------
# 4) Logo quality, all-or-nothing image delivery and a persistent per-image audit.
# ---------------------------------------------------------------------------
V20_LOGO_AUDIT_FILE = "football_logo_audit.json"
V20_LOGO_AUDIT_LIMIT = max(100, int(os.environ.get("V20_LOGO_AUDIT_LIMIT", "1200")))
_V20_LOGO_AUDIT_LOCK = RLock()
_V20_LOGO_CONTEXT = {}


def _v20_logo_audit(event: str, **fields: Any) -> None:
    row = {
        "ts": time.time(),
        "event": str(event or "unknown"),
        "build": BOT_BUILD_ID,
    }
    for key, value in fields.items():
        if isinstance(value, Path):
            value = str(value)
        if isinstance(value, (str, int, float, bool)) or value is None:
            row[str(key)] = value
        elif isinstance(value, (list, tuple)):
            row[str(key)] = [str(item) for item in value]
        elif isinstance(value, dict):
            row[str(key)] = {str(k): str(v) for k, v in value.items()}
        else:
            row[str(key)] = str(value)
    try:
        with _V20_LOGO_AUDIT_LOCK:
            path = persistent_memory_path(V20_LOGO_AUDIT_FILE)
            rows = load_json_list_file(path)
            rows.append(row)
            save_json_list_file(path, rows, limit=V20_LOGO_AUDIT_LIMIT)
    except Exception as exc:
        logging.error("Logo audit write failed: %s | event=%s", short_error(exc, 300), event)


def _v20_logo_badge(size: int) -> str:
    from PIL import ImageFilter
    size = max(32, int(size))
    output = _channel_logo_cache_dir() / f"badge_v20_hq_{size}.png"
    if output.is_file() and output.stat().st_size > 100:
        try:
            with Image.open(output) as probe:
                if probe.size == (size, size):
                    return str(output)
        except Exception:
            try:
                output.unlink()
            except Exception:
                pass
    if not _channel_logo_enabled():
        raise RuntimeError("logo_source_unavailable")
    with Image.open(_channel_logo_resolved_path()) as opened:
        source = ImageOps.exif_transpose(opened).convert("RGBA")
        # Render above target size and downsample once for cleaner text/edges.
        render_size = max(size * 3, 192)
        square = ImageOps.fit(
            source,
            (render_size, render_size),
            method=Image.Resampling.LANCZOS,
            centering=(0.5, 0.5),
        )
        square = square.filter(ImageFilter.UnsharpMask(radius=1.1, percent=125, threshold=2))
        square = square.resize((size, size), Image.Resampling.LANCZOS)
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    badge = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    badge.paste(square, (0, 0), mask)
    border = max(2, round(size * 0.025))
    ImageDraw.Draw(badge).ellipse(
        (border // 2, border // 2, size - 1 - border // 2, size - 1 - border // 2),
        outline=(255, 255, 255, 245),
        width=border,
    )
    tmp = output.with_suffix(".tmp.png")
    badge.save(tmp, "PNG", optimize=True)
    os.replace(tmp, output)
    return str(output)


_channel_logo_badge = _v20_logo_badge


def _v20_brand_image(source: str) -> str:
    from PIL import ImageFilter
    source_text = str(source or "").strip()
    if not source_text:
        raise RuntimeError("empty_image_source")
    if not _channel_logo_enabled():
        _v20_logo_audit("brand_failed", source=source_text, stage="logo_source", error="logo_unavailable")
        raise RuntimeError("Neto Sport logo unavailable; original image will not be sent")
    key = hashlib.sha256(("neto-logo-v20-hq-12pct|" + source_text).encode("utf-8", errors="ignore")).hexdigest()
    folder = _channel_logo_cache_dir() / "photos_v20"
    folder.mkdir(parents=True, exist_ok=True)
    output = folder / f"{key}.jpg"
    if output.is_file() and output.stat().st_size > 500:
        try:
            with Image.open(output) as probe:
                probe.verify()
            _v20_logo_audit("brand_cache_hit", source=source_text, branded_file=str(output))
            return str(output)
        except Exception:
            try:
                output.unlink()
            except Exception:
                pass
    try:
        _v20_logo_audit("download_started", source=source_text)
        raw = _channel_read_image_bytes(source_text)
        _v20_logo_audit("download_succeeded", source=source_text, bytes=len(raw))
    except Exception as exc:
        _v20_logo_audit("brand_failed", source=source_text, stage="download", error=short_error(exc, 500))
        raise
    try:
        with Image.open(io.BytesIO(raw)) as opened:
            base = ImageOps.exif_transpose(opened).convert("RGBA")
        width, height = base.size
        if width < 80 or height < 80:
            raise RuntimeError(f"image_too_small_for_logo:{width}x{height}")
        short_side = min(width, height)
        logo_size = max(34, round(short_side * 0.12))
        badge_path = _v20_logo_badge(logo_size)
        with Image.open(badge_path) as opened_badge:
            badge = opened_badge.convert("RGBA")
        margin = max(8, min(22, round(short_side * 0.014)))
        base.alpha_composite(badge, (margin, margin))
        rgb = base.convert("RGB").filter(ImageFilter.UnsharpMask(radius=0.35, percent=108, threshold=3))
        tmp = output.with_suffix(".tmp.jpg")
        rgb.save(tmp, "JPEG", quality=98, subsampling=0, optimize=True)
        os.replace(tmp, output)
        with Image.open(output) as probe:
            probe.verify()
        _v20_logo_audit(
            "brand_succeeded",
            source=source_text,
            branded_file=str(output),
            width=width,
            height=height,
            logo_size=logo_size,
        )
        return str(output)
    except Exception as exc:
        try:
            output.unlink(missing_ok=True)
        except Exception:
            pass
        _v20_logo_audit("brand_failed", source=source_text, stage="compose_or_save", error=short_error(exc, 500))
        raise RuntimeError("logo_branding_failed; original image blocked: " + short_error(exc, 500))


_channel_brand_image = _v20_brand_image
V20_IMAGE_DOWNLOAD_TIMEOUT_SECONDS = max(3.0, float(os.environ.get("V20_IMAGE_DOWNLOAD_TIMEOUT_SECONDS", "5.0")))
_V9_IMAGE_DOWNLOAD_TIMEOUT_SECONDS = V20_IMAGE_DOWNLOAD_TIMEOUT_SECONDS


def _v20_brand_images(images: list[str]) -> list[str]:
    sources = list(dict.fromkeys(str(value).strip() for value in (images or []) if str(value).strip()))
    if not sources:
        return []
    outputs: list[str | None] = [None] * len(sources)
    errors: list[str] = []
    with ThreadPoolExecutor(max_workers=min(max(1, _V9_IMAGE_BRAND_WORKERS), len(sources)), thread_name_prefix="neto-logo-v20") as executor:
        futures = {executor.submit(_v20_brand_image, source): index for index, source in enumerate(sources)}
        for future in as_completed(futures):
            index = futures[future]
            try:
                outputs[index] = future.result()
            except Exception as exc:
                errors.append(f"#{index + 1} {short_error(exc, 400)}")
    branded = [str(value) for value in outputs if value]
    if len(branded) != len(sources):
        _v20_logo_audit(
            "batch_blocked",
            sources=sources,
            branded_files=branded,
            error=" | ".join(errors) or f"branding_count_mismatch:{len(branded)}/{len(sources)}",
        )
        raise RuntimeError("One or more images could not receive the logo; no original image was sent")
    return branded


_channel_brand_images = _v20_brand_images

# Avoid repeated exact-post media lookup when a direct/X source already supplied
# verified, exact image/video URLs. This removes a common 10–20 second media delay.
_V20_PRE_HYDRATE_EXACT_POST = _reliable_hydrate_exact_post


def _v20_media_already_exact(post: Any) -> bool:
    if not isinstance(post, Post) or not bool(getattr(post, "exact_media_checked", False)):
        return False
    images = list(getattr(post, "image_urls", []) or [])
    videos = list(getattr(post, "video_urls", []) or [])
    if images and callable(globals().get("_real_tweet_photo_url")):
        if not all(_real_tweet_photo_url(value) for value in images):
            return False
    if videos and callable(globals().get("_real_tweet_video_url")):
        if not all(_real_tweet_video_url(value) for value in videos):
            return False
    expects_photo = bool(getattr(post, "photo_expected", False))
    expects_video = bool(
        getattr(post, "has_video", False)
        or getattr(post, "primary_has_video", False)
        or getattr(post, "quoted_has_video", False)
    )
    if expects_photo and not images and not expects_video:
        return False
    if expects_video and not videos:
        return False
    return bool(images or videos or not (expects_photo or expects_video))


def _v20_hydrate_exact_post(post: Any, force: bool = False) -> Any:
    if _v20_media_already_exact(post):
        if isinstance(post, Post):
            post.image_urls = _final_dedupe_exact_photos(getattr(post, "image_urls", []) or [])
        return post
    return _V20_PRE_HYDRATE_EXACT_POST(post, force=force)


_reliable_hydrate_exact_post = _v20_hydrate_exact_post

# Audit and enforce the actual file list handed to Telegram for main-channel image
# sends. Any branding error aborts before Telegram is called.

def _v20_send_branded_to_main(
    post: Post,
    message: str,
    images: list[str],
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    exact_images = _final_dedupe_exact_photos(images or selected_post_images(post))
    if not exact_images:
        _v20_logo_audit("send_blocked", post_id=getattr(post, "post_id", ""), stage="no_exact_images")
        raise RuntimeError("No exact images available; unbranded fallback is forbidden")
    branded = _v20_brand_images(exact_images)
    if any(path in exact_images for path in branded) or not all(os.path.isfile(path) for path in branded):
        _v20_logo_audit("send_blocked", post_id=getattr(post, "post_id", ""), stage="branding_verification", files=branded)
        raise RuntimeError("Branding verification failed; original image will not be sent")
    if not _acceptance_caption_fits(message):
        raise RuntimeError(hebrew_block_reason("caption_too_long_for_single_media_message"))
    message_ids: dict[str, int] = {}
    errors: list[str] = []
    for chat_id in TELEGRAM_CHAT_IDS:
        try:
            _v20_logo_audit(
                "telegram_send_started",
                post_id=getattr(post, "post_id", ""),
                chat_id=str(chat_id),
                source_files=exact_images,
                telegram_files=branded,
                route="main",
            )
            response = _channel_send_photo_set_to_chat(
                str(chat_id), branded, message,
                reply_id=(reply_message_ids or {}).get(str(chat_id)),
            )
            ids = _telegram_result_message_ids(response)
            if ids:
                message_ids[str(chat_id)] = int(ids[0])
            _v20_logo_audit(
                "telegram_send_succeeded",
                post_id=getattr(post, "post_id", ""),
                chat_id=str(chat_id),
                telegram_files=branded,
                message_ids=ids,
                route="main",
            )
        except Exception as exc:
            errors.append(f"{chat_id}: {short_error(exc, 500)}")
            _v20_logo_audit(
                "telegram_send_failed",
                post_id=getattr(post, "post_id", ""),
                chat_id=str(chat_id),
                telegram_files=branded,
                route="main",
                error=short_error(exc, 500),
            )
            logging.error("Branded photo send failed for chat %s: %s", chat_id, exc)
    if not message_ids:
        raise RuntimeError("Branded photo broadcast failed for all chats: " + " | ".join(errors))
    return message_ids, f"{len(branded)} branded_images_v20"


_channel_send_branded_to_main = _v20_send_branded_to_main

