def _v20_send_full_control_candidate(post: Post, token: str, message_html: str) -> list[int]:
    clean = _v20_format_message(post, message_html)
    _reliable_hydrate_exact_post(post, force=True)
    if _acceptance_post_requires_video(post):
        return _V20_PRE_CONTROL_CANDIDATE(post, token, clean)
    images = selected_post_images(post)
    if not images:
        if bool(getattr(post, "photo_expected", False)):
            _v20_logo_audit("quiet_send_blocked", post_id=getattr(post, "post_id", ""), stage="original_photo_missing")
            send_control_text(
                "⛔ התמונה המקורית לא נמצאה ולכן הפוסט לא הוכן בלי לוגו.",
                None,
                control_delete_message_reply_markup(),
            )
            return []
        return _V20_PRE_CONTROL_CANDIDATE(post, token, clean)
    if not CONTROL_CHAT_ID:
        return []
    try:
        branded = _v20_brand_images(images)
        markup = ensure_delete_button_reply_markup(control_send_to_main_reply_markup(token))
        _v20_logo_audit(
            "telegram_send_started",
            post_id=getattr(post, "post_id", ""),
            chat_id=str(CONTROL_CHAT_ID),
            source_files=images,
            telegram_files=branded,
            route="quiet",
        )
        response = _channel_send_photo_set_to_chat(
            str(CONTROL_CHAT_ID), branded, clean,
            reply_markup=markup if len(branded) == 1 else None,
        )
        ids = _telegram_result_message_ids(response)
        if ids:
            CONTROL_TELEGRAM_MEDIA_CACHE[token] = list(ids)
            _save_prepared_media_ids(token, ids)
            if len(branded) > 1:
                send_control_html("הפוסט מוכן לשליחה.", control_send_to_main_reply_markup(token))
        _v20_logo_audit(
            "telegram_send_succeeded",
            post_id=getattr(post, "post_id", ""),
            chat_id=str(CONTROL_CHAT_ID),
            telegram_files=branded,
            message_ids=ids,
            route="quiet",
        )
        return ids
    except Exception as exc:
        _v20_logo_audit(
            "telegram_send_failed",
            post_id=getattr(post, "post_id", ""),
            chat_id=str(CONTROL_CHAT_ID),
            route="quiet",
            error=short_error(exc, 600),
        )
        logging.exception("V20 branded quiet-channel preview failed")
        send_control_text(
            "⛔ הוספת הלוגו נכשלה ולכן התמונה המקורית לא נשלחה:\n" + short_error(exc, 900),
            None,
            control_delete_message_reply_markup(),
        )
        return []


_send_full_control_candidate = _v20_send_full_control_candidate

