def _v20_audited_photo_set_sender(
    chat_id: str,
    images: list[str],
    caption: str,
    reply_markup: dict[str, Any] | None = None,
    reply_id: int | None = None,
) -> dict[str, Any]:
    files = [str(value or "").strip() for value in (images or []) if str(value or "").strip()]
    if not files or not all(os.path.isfile(path) for path in files):
        _v20_logo_audit(
            "telegram_send_blocked",
            chat_id=str(chat_id),
            telegram_files=files,
            stage="non_local_or_missing_branded_file",
        )
        raise RuntimeError("Only verified local branded image files may be sent")
    route = "quiet" if str(chat_id) == str(CONTROL_CHAT_ID) else "main"
    _v20_logo_audit(
        "telegram_file_handoff",
        chat_id=str(chat_id),
        telegram_files=files,
        route=route,
        has_reply_markup=bool(reply_markup),
    )
    try:
        return _V20_PRE_PHOTO_SET_SENDER(
            chat_id, files, caption, reply_markup=reply_markup, reply_id=reply_id
        )
    except Exception as exc:
        _v20_logo_audit(
            "telegram_file_handoff_failed",
            chat_id=str(chat_id),
            telegram_files=files,
            route=route,
            error=short_error(exc, 500),
        )
        raise


_channel_send_photo_set_to_chat = _v20_audited_photo_set_sender


