BOT_BUILD_ID = "winner-v21-fast-all-source-logo-hard-gate-topic-dedupe-2026-08-03"

# ---------------------------------------------------------------------------
# 1) Use the exact supplied Neto Sport logo as the built-in deployment fallback.
#    An explicit NETO_SPORT_LOGO_PATH still wins when present and valid.
# ---------------------------------------------------------------------------
_V21_LOGO_SHA256 = "456bf86218430b3c660e6ae5f355e96f5bf59bd7b454e9bc745cac32e7df729e"
_V21_LOGO_EMBEDDED_B64 = """"""
_V21_EXPLICIT_LOGO_PATH = os.environ.get("NETO_SPORT_LOGO_PATH", "").strip()
_V21_BRANDED_LOCK = RLock()
_V21_BRANDED_FILES: dict[str, dict[str, Any]] = {}
_V21_LOGO_CONTEXT_LOCAL = __import__("threading").local()


def _v21_logo_resolved_path() -> str:
    global _CHANNEL_LOGO_SOURCE_PATH
    if _V21_EXPLICIT_LOGO_PATH and os.path.isfile(_V21_EXPLICIT_LOGO_PATH):
        _CHANNEL_LOGO_SOURCE_PATH = _V21_EXPLICIT_LOGO_PATH
        return _CHANNEL_LOGO_SOURCE_PATH
    folder = _channel_logo_cache_dir()
    folder.mkdir(parents=True, exist_ok=True)
    output = folder / f"neto_sport_source_v21_{_V21_LOGO_SHA256[:16]}.jpg"
    valid = False
    if output.is_file() and output.stat().st_size > 1000:
        try:
            valid = hashlib.sha256(output.read_bytes()).hexdigest() == _V21_LOGO_SHA256
        except Exception:
            valid = False
    if not valid:
        raw = base64.b64decode(_V21_LOGO_EMBEDDED_B64)
        if hashlib.sha256(raw).hexdigest() != _V21_LOGO_SHA256:
            raise RuntimeError("embedded_logo_checksum_mismatch")
        tmp = output.with_suffix(".tmp.jpg")
        tmp.write_bytes(raw)
        os.replace(tmp, output)
    _CHANNEL_LOGO_SOURCE_PATH = str(output)
    return _CHANNEL_LOGO_SOURCE_PATH


_channel_logo_resolved_path = _v21_logo_resolved_path
try:
    _CHANNEL_LOGO_SOURCE_PATH = _v21_logo_resolved_path()
    _CHANNEL_LOGO_BADGE_CACHE.clear()
except Exception as _v21_logo_init_exc:
    logging.error("V21 logo initialization failed: %s", short_error(_v21_logo_init_exc, 500))


def _v21_logo_badge(size: int) -> str:
    from PIL import ImageFilter
    size = max(48, int(size))
    folder = _channel_logo_cache_dir() / "badges_v21"
    folder.mkdir(parents=True, exist_ok=True)
    output = folder / f"badge_{_V21_LOGO_SHA256[:12]}_{size}.png"
    if output.is_file() and output.stat().st_size > 300:
        try:
            with Image.open(output) as probe:
                if probe.size == (size, size):
                    return str(output)
        except Exception:
            try:
                output.unlink()
            except Exception:
                pass
    if not _channel_logo_enabled():
        raise RuntimeError("logo_source_unavailable")
    with Image.open(_channel_logo_resolved_path()) as opened:
        source = ImageOps.exif_transpose(opened).convert("RGBA")
        render_size = max(size * 4, 320)
        contained = ImageOps.contain(source, (render_size, render_size), method=Image.Resampling.LANCZOS)
        canvas = Image.new("RGBA", (render_size, render_size), (0, 0, 0, 0))
        x = (render_size - contained.width) // 2
        y = (render_size - contained.height) // 2
        canvas.alpha_composite(contained, (x, y))
        canvas = canvas.filter(ImageFilter.UnsharpMask(radius=1.0, percent=135, threshold=2))
        badge = canvas.resize((size, size), Image.Resampling.LANCZOS)
    tmp = output.with_suffix(".tmp.png")
    badge.save(tmp, "PNG", optimize=True)
    os.replace(tmp, output)
    return str(output)


_channel_logo_badge = _v21_logo_badge


def _v21_register_branded(path: str, source: str, *, width: int, height: int, logo_size: int) -> None:
    try:
        digest = hashlib.sha256(Path(path).read_bytes()).hexdigest()
    except Exception:
        digest = ""
    with _V21_BRANDED_LOCK:
        _V21_BRANDED_FILES[os.path.realpath(path)] = {
            "source": str(source),
            "sha256": digest,
            "width": int(width),
            "height": int(height),
            "logo_size": int(logo_size),
            "ts": time.time(),
        }
        if len(_V21_BRANDED_FILES) > 2500:
            oldest = sorted(_V21_BRANDED_FILES, key=lambda key: float(_V21_BRANDED_FILES[key].get("ts", 0.0)))[:500]
            for key in oldest:
                _V21_BRANDED_FILES.pop(key, None)


def _v21_verified_brand_info(path: str) -> dict[str, Any] | None:
    real = os.path.realpath(str(path or ""))
    with _V21_BRANDED_LOCK:
        info = dict(_V21_BRANDED_FILES.get(real, {}))
    if info and os.path.isfile(real):
        return info
    expected_parent = os.path.realpath(str(_channel_logo_cache_dir() / "photos_v21"))
    if os.path.isfile(real) and os.path.dirname(real) == expected_parent:
        try:
            with Image.open(real) as probe:
                width, height = probe.size
                probe.verify()
            info = {
                "source": "cache_recovered",
                "sha256": hashlib.sha256(Path(real).read_bytes()).hexdigest(),
                "width": width,
                "height": height,
                "logo_size": 0,
                "ts": time.time(),
            }
            with _V21_BRANDED_LOCK:
                _V21_BRANDED_FILES[real] = info
            return info
        except Exception:
            return None
    return None


def _v21_brand_image(source: str) -> str:
    from PIL import ImageFilter
    source_text = str(source or "").strip()
    if not source_text:
        raise RuntimeError("empty_image_source")
    already = _v21_verified_brand_info(source_text)
    if already:
        return os.path.realpath(source_text)
    if not _channel_logo_enabled():
        _v20_logo_audit("brand_failed", source=source_text, stage="logo_source", error="logo_unavailable")
        raise RuntimeError("Neto Sport logo unavailable; original image will not be sent")
    key = hashlib.sha256(("neto-logo-v21|" + _V21_LOGO_SHA256 + "|" + source_text).encode("utf-8", errors="ignore")).hexdigest()
    folder = _channel_logo_cache_dir() / "photos_v21"
    folder.mkdir(parents=True, exist_ok=True)
    output = folder / f"{key}.jpg"
    if output.is_file() and output.stat().st_size > 800:
        try:
            with Image.open(output) as probe:
                width, height = probe.size
                probe.verify()
            _v21_register_branded(str(output), source_text, width=width, height=height, logo_size=0)
            _v20_logo_audit("brand_cache_hit", source=source_text, branded_file=str(output), version="v21")
            return str(output)
        except Exception:
            try:
                output.unlink()
            except Exception:
                pass
    try:
        _v20_logo_audit("download_started", source=source_text, version="v21")
        raw = _channel_read_image_bytes(source_text)
        if not raw or len(raw) < 200:
            raise RuntimeError("downloaded_image_empty_or_too_small")
        _v20_logo_audit("download_succeeded", source=source_text, bytes=len(raw), version="v21")
    except Exception as exc:
        _v20_logo_audit("brand_failed", source=source_text, stage="download", error=short_error(exc, 500), version="v21")
        raise
    try:
        with Image.open(io.BytesIO(raw)) as opened:
            base = ImageOps.exif_transpose(opened).convert("RGBA")
        width, height = base.size
        if width < 100 or height < 100:
            raise RuntimeError(f"image_too_small_for_logo:{width}x{height}")
        short_side = min(width, height)
        logo_size = max(64, round(short_side * 0.13))
        logo_size = min(logo_size, max(64, round(short_side * 0.18)))
        badge_path = _v21_logo_badge(logo_size)
        with Image.open(badge_path) as opened_badge:
            badge = opened_badge.convert("RGBA")
        margin = max(8, min(26, round(short_side * 0.015)))
        base.alpha_composite(badge, (margin, margin))
        rgb = base.convert("RGB").filter(ImageFilter.UnsharpMask(radius=0.30, percent=108, threshold=3))
        tmp = output.with_suffix(".tmp.jpg")
        rgb.save(tmp, "JPEG", quality=98, subsampling=0, optimize=True)
        os.replace(tmp, output)
        with Image.open(output) as probe:
            out_size = probe.size
            probe.verify()
        if out_size != (width, height):
            raise RuntimeError(f"branded_dimension_mismatch:{out_size}!={(width, height)}")
        _v21_register_branded(str(output), source_text, width=width, height=height, logo_size=logo_size)
        _v20_logo_audit(
            "brand_succeeded", source=source_text, branded_file=str(output), width=width,
            height=height, logo_size=logo_size, logo_sha256=_V21_LOGO_SHA256, version="v21",
        )
        return str(output)
    except Exception as exc:
        try:
            output.unlink(missing_ok=True)
        except Exception:
            pass
        _v20_logo_audit("brand_failed", source=source_text, stage="compose_or_save", error=short_error(exc, 500), version="v21")
        raise RuntimeError("logo_branding_failed; original image blocked: " + short_error(exc, 500))


_channel_brand_image = _v21_brand_image


def _v21_brand_images(images: list[str]) -> list[str]:
    sources = list(dict.fromkeys(str(value).strip() for value in (images or []) if str(value).strip()))
    if not sources:
        return []
    outputs: list[str | None] = [None] * len(sources)
    errors: list[str] = []
    workers = min(max(1, int(globals().get("_V9_IMAGE_BRAND_WORKERS", 4))), len(sources))
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="neto-logo-v21") as executor:
        futures = {executor.submit(_v21_brand_image, source): index for index, source in enumerate(sources)}
        for future in as_completed(futures):
            index = futures[future]
            try:
                outputs[index] = future.result()
            except Exception as exc:
                errors.append(f"#{index + 1} {short_error(exc, 500)}")
    branded = [str(value) for value in outputs if value]
    if len(branded) != len(sources) or any(_v21_verified_brand_info(path) is None for path in branded):
        _v20_logo_audit(
            "batch_blocked", sources=sources, branded_files=branded,
            error=" | ".join(errors) or f"branding_count_mismatch:{len(branded)}/{len(sources)}", version="v21",
        )
        raise RuntimeError("One or more images could not receive a verified logo; no original image was sent")
    return branded


_channel_brand_images = _v21_brand_images

# The final Telegram photo boundary accepts only files produced and verified by
# the V21 branding stage. A merely local original download is not sufficient.
_V21_PRE_PHOTO_SET_SENDER = _channel_send_photo_set_to_chat


def _v21_verified_photo_set_sender(
    chat_id: str,
    images: list[str],
    caption: str,
    reply_markup: dict[str, Any] | None = None,
    reply_id: int | None = None,
) -> dict[str, Any]:
    files = [os.path.realpath(str(value or "").strip()) for value in (images or []) if str(value or "").strip()]
    infos = [_v21_verified_brand_info(path) for path in files]
    route = "quiet" if str(chat_id) == str(CONTROL_CHAT_ID) else "main"
    if not files or any(info is None for info in infos):
        _v20_logo_audit(
            "telegram_send_blocked", chat_id=str(chat_id), telegram_files=files,
            stage="file_not_verified_as_v21_branded", route=route, version="v21",
        )
        raise RuntimeError("Unbranded or unverified image handoff blocked before Telegram")
    _v20_logo_audit(
        "telegram_file_handoff", chat_id=str(chat_id), telegram_files=files,
        source_files=[str((info or {}).get("source", "")) for info in infos],
        file_sha256=[str((info or {}).get("sha256", "")) for info in infos],
        route=route, has_reply_markup=bool(reply_markup), version="v21",
    )
    try:
        response = _V21_PRE_PHOTO_SET_SENDER(
            chat_id, files, caption, reply_markup=reply_markup, reply_id=reply_id
        )
        _v20_logo_audit(
            "telegram_send_succeeded", chat_id=str(chat_id), telegram_files=files,
            message_ids=_telegram_result_message_ids(response), route=route, version="v21",
        )
        return response
    except Exception as exc:
        _v20_logo_audit(
            "telegram_file_handoff_failed", chat_id=str(chat_id), telegram_files=files,
            route=route, error=short_error(exc, 600), version="v21",
        )
        raise


_channel_send_photo_set_to_chat = _v21_verified_photo_set_sender

# All actual main/manual routes must hydrate exact media, brand the complete set,
# and abort rather than silently downgrade to an original or text-only photo post.

def _v21_send_verified_branded_to_main(
    post: Post,
    message: str,
    images: list[str],
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    exact_images = _final_dedupe_exact_photos(images or selected_post_images(post))
    if not exact_images:
        _v20_logo_audit("send_blocked", post_id=getattr(post, "post_id", ""), stage="no_exact_images", version="v21")
        raise RuntimeError("No exact images available; unbranded fallback is forbidden")
    branded = _v21_brand_images(exact_images)
    if not _acceptance_caption_fits(message):
        raise RuntimeError(hebrew_block_reason("caption_too_long_for_single_media_message"))
    message_ids: dict[str, int] = {}
    errors: list[str] = []
    for chat_id in TELEGRAM_CHAT_IDS:
        try:
            response = _channel_send_photo_set_to_chat(
                str(chat_id), branded, message,
                reply_id=(reply_message_ids or {}).get(str(chat_id)),
            )
            ids = _telegram_result_message_ids(response)
            if ids:
                message_ids[str(chat_id)] = int(ids[0])
        except Exception as exc:
            errors.append(f"{chat_id}: {short_error(exc, 500)}")
            logging.error("V21 branded photo send failed for chat %s: %s", chat_id, exc)
    if not message_ids:
        raise RuntimeError("Branded photo broadcast failed for all chats: " + " | ".join(errors))
    return message_ids, f"{len(branded)} verified_branded_images_v21"


_channel_send_branded_to_main = _v21_send_verified_branded_to_main
_V21_PRE_SEND_PREPARED = send_prepared_message_to_main
_V21_PRE_MANUAL_SEND_PREPARED = manual_force_send_prepared_message


def _v21_message_media_state(post: Post, supplied_images: list[str], video_url: str) -> tuple[list[str], bool, bool]:
    try:
        _reliable_hydrate_exact_post(post, force=True)
    except Exception as exc:
        logging.debug("V21 exact-media hydration retained known media: %s", short_error(exc, 300))
    exact_images = _final_dedupe_exact_photos(supplied_images or selected_post_images(post))
    expects_photo = bool(getattr(post, "photo_expected", False) or supplied_images or exact_images)
    has_video = bool(video_url or _acceptance_post_requires_video(post))
    return exact_images, expects_photo, has_video


def _v21_send_prepared_message_to_main(
    post: Post,
    message: str,
    images: list[str],
    video_url: str = "",
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    clean = _v20_format_message(post, message)
    exact_images, expects_photo, has_video = _v21_message_media_state(post, images, video_url)
    if exact_images and not has_video:
        return _v21_send_verified_branded_to_main(post, clean, exact_images, reply_message_ids=reply_message_ids)
    if expects_photo and not exact_images and not has_video:
        _v20_logo_audit("send_blocked", post_id=getattr(post, "post_id", ""), stage="expected_photo_missing", route="main", version="v21")
        raise RuntimeError("Expected photo is missing; original/text fallback is forbidden")
    return _V21_PRE_SEND_PREPARED(post, clean, images, video_url=video_url, reply_message_ids=reply_message_ids)


def _v21_manual_force_send_prepared_message(
    post: Post,
    message: str,
    images: list[str],
    video_url: str = "",
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    clean = _v20_format_message(post, message)
    exact_images, expects_photo, has_video = _v21_message_media_state(post, images, video_url)
    if exact_images and not has_video:
        return _v21_send_verified_branded_to_main(post, clean, exact_images, reply_message_ids=reply_message_ids)
    if expects_photo and not exact_images and not has_video:
        _v20_logo_audit("send_blocked", post_id=getattr(post, "post_id", ""), stage="expected_photo_missing", route="manual", version="v21")
        raise RuntimeError("Expected photo is missing; original/text fallback is forbidden")
    return _V21_PRE_MANUAL_SEND_PREPARED(post, clean, images, video_url=video_url, reply_message_ids=reply_message_ids)


send_prepared_message_to_main = _v21_send_prepared_message_to_main
manual_force_send_prepared_message = _v21_manual_force_send_prepared_message
_base_send_prepared_message_to_main = manual_force_send_prepared_message

_V21_PRE_CONTROL_CANDIDATE = _send_full_control_candidate


def _v21_send_full_control_candidate(post: Post, token: str, message_html: str) -> list[int]:
    clean = _v20_format_message(post, message_html)
    try:
        _reliable_hydrate_exact_post(post, force=True)
    except Exception as exc:
        logging.debug("V21 quiet exact-media hydration retained known media: %s", short_error(exc, 300))
    images = _final_dedupe_exact_photos(selected_post_images(post))
    has_video = bool(_acceptance_post_requires_video(post))
    if bool(getattr(post, "photo_expected", False)) and not images and not has_video:
        _v20_logo_audit("quiet_send_blocked", post_id=getattr(post, "post_id", ""), stage="expected_photo_missing", version="v21")
        send_control_text(
            "⛔ התמונה המקורית לא נמצאה ולכן הפוסט לא הוכן ולא נשלח בלי לוגו.",
            None,
            control_delete_message_reply_markup(),
        )
        return []
    try:
        return _V21_PRE_CONTROL_CANDIDATE(post, token, clean)
    except Exception as exc:
        _v20_logo_audit("quiet_send_failed", post_id=getattr(post, "post_id", ""), error=short_error(exc, 600), version="v21")
        raise


_send_full_control_candidate = _v21_send_full_control_candidate

# ---------------------------------------------------------------------------
# 2) Correct the ordinary-reporter 7-word threshold. V20 renamed the old
#    15-word reason but still allowed the old blocker to reject 7-14-word posts.
# ---------------------------------------------------------------------------
_V21_PRE_LOCAL_BLOCK_REASON = pre_send_final_local_block_reason


def _v21_pre_send_final_local_block_reason(post: Post) -> str:
    if _v20_is_facts_post(post):
        return str(_V21_PRE_LOCAL_BLOCK_REASON(post) or "")
    count = _v20_regular_report_word_count(post)
    if count < REGULAR_REPORT_MIN_WORDS:
        return "report_under_7_words"
    reason = str(_V21_PRE_LOCAL_BLOCK_REASON(post) or "")
    if "report_under_15_words" in reason or "report_under_7_words" in reason:
        return ""
    if _v21_is_quote_only_post(post):
        return "quote_only_without_news"
    return reason


# ---------------------------------------------------------------------------
# 3) Pure quotation/interview posts without a concrete news update are blocked.
#    A confirmation/transfer fact before the quotation keeps a post publishable.
# ---------------------------------------------------------------------------
_V21_QUOTE_MARKER_RE = re.compile(
    r"(?iu)(?:🗣|🎙|[\"“”„]|(?:אומר|אמר|אומרת|אמרה|לדבריו|לדבריה|ציין|ציינה|הוסיף|הוסיפה)\s+(?:ש|כי)|"
    r"\b(?:says|said|told|speaking|quote)\b)"
)
_V21_CONCRETE_NEWS_RE = re.compile(
    r"(?iu)(?:\b(?:official|confirmed|confirms|joins?|joined|signs?|signed|agreed|agreement|deal\s+done|"
    r"bid|offer|medical|contract|transfer|loan|appointed|sacked|leaves?|left)\b|"
    r"רשמי|אושר|אושרה|מאשר|מאשרת|הצטרף|מצטרף|חתם|יחתום|סיכם|סוכם|הושג\s+סיכום|"
    r"הוגשה\s+הצעה|הצעה\s+רשמית|בדיקות\s+רפואיות|חוזה|העברה|השאלה|מונה|פוטר|עזב)"
)
_V21_QUOTE_ONLY_PREFIX_RE = re.compile(
    r"(?iu)^\s*(?:[\U0001F1E6-\U0001F1FF\U0001F300-\U0001FAFF\u2600-\u27BF\ufe0f\u200d]+\s*)*"
    r".{0,100}?(?:אומר|אמר|אומרת|אמרה|לדבריו|לדבריה|ציין|ציינה|הוסיף|הוסיפה|says|said|told)\b"
)


def _v21_source_text(post: Any) -> str:
    try:
        value = _final_source_text(post)
    except Exception:
        value = "\n".join(filter(None, [str(getattr(post, "text", "") or ""), str(getattr(post, "quoted_text", "") or "")]))
    return html.unescape(re.sub(r"<[^>]+>", "", str(value or ""))).strip()


def _v21_is_quote_only_post(post: Any) -> bool:
    if not isinstance(post, Post) or _v20_is_facts_post(post):
        return False
    text = _v21_source_text(post)
    if not text or not _V21_QUOTE_MARKER_RE.search(text):
        return False
    quote_positions = [pos for pos in (text.find('"'), text.find("“"), text.find("🗣"), text.find("🎙")) if pos >= 0]
    first_quote = min(quote_positions) if quote_positions else len(text)
    prefix = text[:first_quote].strip()
    if _V21_CONCRETE_NEWS_RE.search(prefix):
        return False
    # A quote-attribution opening without a concrete action is not a news item.
    if _V21_QUOTE_ONLY_PREFIX_RE.search(text):
        return True
    quoted_chars = sum(len(match.group(0)) for match in re.finditer(r"[\"“][^\"”]{18,}[\"”]?", text, flags=re.S))
    if quoted_chars >= max(40, int(len(text) * 0.45)) and not _V21_CONCRETE_NEWS_RE.search(prefix):
        return True
    return bool(text.lstrip().startswith(("🗣", "🎙")) and not _V21_CONCRETE_NEWS_RE.search(prefix))


_V21_PRE_INTERVIEW_POST = is_interview_post


def is_interview_post(post: Post, *args: Any, **kwargs: Any) -> bool:
    if _v21_is_quote_only_post(post):
        return True
    return bool(_V21_PRE_INTERVIEW_POST(post, *args, **kwargs))


_V21_PRE_HEBREW_BLOCK_REASON = hebrew_block_reason


def _v21_hebrew_block_reason(reason: str) -> str:
    if str(reason or "") == "quote_only_without_news":
        return "ציטוט או ראיון בלבד ללא עדכון חדשותי מאושר"
    return _V21_PRE_HEBREW_BLOCK_REASON(reason)


hebrew_block_reason = _v21_hebrew_block_reason
pre_send_final_local_block_reason = _v21_pre_send_final_local_block_reason

# ---------------------------------------------------------------------------
# 4) Robust same-event comparison and same-cycle collapse. Only the first
#    confirmed report is retained when later posts repeat the same player/team
#    event; a genuinely later stage can replace an earlier rumor, but never adds
#    a second same-cycle message. Fabrizio HERE WE GO remains protected.
# ---------------------------------------------------------------------------
_V21_PRE_SAME_EVENT_TEXT = _v9_same_event_text
_V21_EVENT_TOKEN_RE = re.compile(r"[A-Za-z\u0590-\u05FF][A-Za-z\u0590-\u05FF׳'’\-]{2,}")
_V21_EVENT_STOPWORDS = {
    "רשמי", "דיווח", "בלעדי", "הידיעה", "החדש", "חדשה", "שחקן", "שחקנה", "הקשר", "הקבוצה",
    "מועדון", "לאחר", "עבור", "ביחס", "מאוד", "היום", "אומר", "אמר", "אושרה", "אושר", "מאשרת",
    "מצטרף", "הצטרף", "חתם", "חוזה", "העברה", "חופשית", "חופשי", "שנתיים", "official", "confirmed",
    "joins", "joined", "signed", "contract", "transfer", "free", "agent", "player", "club", "says", "said",
}
_V21_STAGE_OFFICIAL_RE = re.compile(r"(?iu)(?:רשמי|אושר|אושרה|מאשר|מאשרת|הצטרף|מצטרף|חתם|שחקנה\s+החדש|\bofficial\b|\bconfirmed\b|\bjoined\b|\bsigned\b)")
_V21_STAGE_AGREED_RE = re.compile(r"(?iu)(?:HERE\s+WE\s+GO|העסקה\s+סוכמה|הושג\s+סיכום|סיכום\s+מלא|\bagreed\b|\bagreement\b|deal\s+done)")
_V21_STAGE_TALKS_RE = re.compile(r"(?iu)(?:שיחות\s+מתקדמות|משא\s+ומתן|הוגשה\s+הצעה|\badvanced\s+talks\b|\bnegotiations\b|\bbid\b|\boffer\b)")
_V21_STAGE_RUMOR_RE = re.compile(r"(?iu)(?:מקושר|מעוניינת|מעוניין|בוחנת|שוקלת|\blinked\b|\binterested\b|\bconsidering\b)")


def _v21_normalize_event_token(token: str) -> str:
    clean = str(token or "").strip("-'׳’").casefold()
    # Hebrew frequently attaches a one-letter conjunction/preposition to a name:
    # שג'ורדן / וג'ורדן / לצ'לסי. Normalize only safe cases; team detection still
    # uses the canonical entity matcher and therefore does not depend on this.
    if len(clean) >= 6 and clean[0] in "שו" and re.match(r"[א-ת]", clean[1:2]):
        clean = clean[1:]
    elif len(clean) >= 6 and clean[0] in "בלכמ" and ("'" in clean[1:] or "׳" in clean[1:]):
        clean = clean[1:]
    return clean


def _v21_event_tokens(value: Any) -> list[str]:
    plain = html.unescape(re.sub(r"<[^>]+>", " ", str(value or ""))).casefold()
    tokens = []
    for token in _V21_EVENT_TOKEN_RE.findall(plain):
        clean = _v21_normalize_event_token(token)
        if len(clean) < 4 or clean in _V21_EVENT_STOPWORDS:
            continue
        tokens.append(clean)
    return tokens


def _v21_name_bigrams(value: Any) -> set[str]:
    tokens = _v21_event_tokens(value)
    result: set[str] = set()
    for left, right in zip(tokens, tokens[1:]):
        if left in _V21_EVENT_STOPWORDS or right in _V21_EVENT_STOPWORDS:
            continue
        result.add(left + " " + right)
    return result


def _v21_team_entities(value: Any) -> set[str]:
    matcher = globals().get("_canonical_event_entity_ids")
    if callable(matcher):
        try:
            return {str(item) for item in (matcher(str(value or "")) or set()) if str(item).startswith("team:")}
        except Exception:
            pass
    return set()


def _v21_event_stage(value: Any) -> int:
    text = str(value or "")
    if _V21_STAGE_OFFICIAL_RE.search(text):
        return 4
    if _V21_STAGE_AGREED_RE.search(text):
        return 3
    if _V21_STAGE_TALKS_RE.search(text):
        return 2
    if _V21_STAGE_RUMOR_RE.search(text):
        return 1
    return 0


def _v21_same_event_fallback(current_text: str, previous_text: str) -> tuple[bool, float]:
    current_teams = _v21_team_entities(current_text)
    previous_teams = _v21_team_entities(previous_text)
    shared_teams = current_teams & previous_teams
    current_tokens = set(_v21_event_tokens(current_text))
    previous_tokens = set(_v21_event_tokens(previous_text))
    shared_tokens = current_tokens & previous_tokens
    shared_names = _v21_name_bigrams(current_text) & _v21_name_bigrams(previous_text)
    current_families = set(_v9_action_families(current_text))
    previous_families = set(_v9_action_families(previous_text))
    family_overlap = bool(current_families & previous_families)
    quote_side = bool(_V21_QUOTE_MARKER_RE.search(current_text) or _V21_QUOTE_MARKER_RE.search(previous_text))
    identity_strength = len(shared_names) * 2 + min(4, len(shared_tokens)) + (2 if shared_teams else 0)
    candidate = bool(
        shared_teams
        and (
            bool(shared_names)
            or len(shared_tokens) >= 3
        )
        and (family_overlap or quote_side or (_v21_event_stage(current_text) >= 3 and _v21_event_stage(previous_text) >= 3))
    )
    score = min(0.99, 0.42 + 0.08 * identity_strength + (0.10 if family_overlap else 0.0))
    if not candidate:
        return False, score
    previous_stage = _v21_event_stage(previous_text)
    current_stage = _v21_event_stage(current_text)
    # A true movement from rumor/talks to agreement/official is a new stage.
    if current_stage > previous_stage and previous_stage < 3 and current_stage >= 3:
        return False, score
    return True, score


def _v21_same_event_text(current_text: str, previous_text: str) -> tuple[bool, float]:
    same, score = _V21_PRE_SAME_EVENT_TEXT(current_text, previous_text)
    if same:
        return same, score
    fallback_same, fallback_score = _v21_same_event_fallback(current_text, previous_text)
    return fallback_same, max(float(score or 0.0), fallback_score)


_v9_same_event_text = _v21_same_event_text


def _v21_merge_candidate_ids(target: Post, duplicate: Post, duplicate_username: str) -> None:
    target.dedupe_ids = list(dict.fromkeys([*(getattr(target, "dedupe_ids", []) or []), *(getattr(duplicate, "dedupe_ids", []) or [])]))
    sources = list(getattr(target, "merged_sources", []) or [getattr(target, "username", "")])
    sources.extend(list(getattr(duplicate, "merged_sources", []) or [duplicate_username]))
    setattr(target, "merged_sources", list(dict.fromkeys(str(item) for item in sources if str(item))))
    links = list(getattr(target, "collapsed_duplicate_links", []) or [])
    links.append(str(getattr(duplicate, "link", "") or ""))
    setattr(target, "collapsed_duplicate_links", list(dict.fromkeys(item for item in links if item)))


_V21_PRE_CLUSTER_PARALLEL = cluster_parallel_candidates


def cluster_parallel_candidates(candidates: list[tuple[str, Post, float]]) -> list[tuple[str, Post, float]]:
    if len(candidates) <= 1:
        return candidates
    indexed = list(enumerate(candidates))
    indexed.sort(key=lambda pair: (float(getattr(pair[1][1], "published_ts", 0.0) or 0.0), pair[0]))
    kept: list[tuple[int, tuple[str, Post, float]]] = []
    for original_index, candidate in indexed:
        username, post, _found = candidate
        if _final_is_fabrizio_here_we_go(post):
            kept.append((original_index, candidate))
            continue
        current_text = _v21_source_text(post)
        matched_index: int | None = None
        for pos, (_kept_order, kept_candidate) in enumerate(kept):
            kept_username, kept_post, _kept_found = kept_candidate
            if _final_is_fabrizio_here_we_go(kept_post):
                continue
            same, _score = _v21_same_event_text(current_text, _v21_source_text(kept_post))
            if same:
                matched_index = pos
                break
        if matched_index is None:
            kept.append((original_index, candidate))
            continue
        kept_order, kept_candidate = kept[matched_index]
        kept_username, kept_post, kept_found = kept_candidate
        old_stage = _v21_event_stage(_v21_source_text(kept_post))
        new_stage = _v21_event_stage(current_text)
        # Replace an early rumor/talks with the later concrete agreement/official,
        # but still keep only one same-cycle message.
        if new_stage >= 3 and old_stage < 3:
            _v21_merge_candidate_ids(post, kept_post, kept_username)
            kept[matched_index] = (min(kept_order, original_index), candidate)
        else:
            _v21_merge_candidate_ids(kept_post, post, username)
        logging.info(
            "V21 same-event collapse: kept @%s and suppressed @%s | %s",
            kept[matched_index][1][0], username, getattr(post, "link", ""),
        )
    return [candidate for _order, candidate in sorted(kept, key=lambda item: item[0])]


