def process_control_update(update: dict[str, Any]) -> None:
    callback = update.get("callback_query") or {}
    data = str(callback.get("data", "") or "") if callback else ""
    message = callback.get("message", {}) or {}
    callback_id = str(callback.get("id", "") or "")
    message_id = message.get("message_id")

    if data == "football_menu_sources_writers_v27":
        if callback_id:
            answer_control_callback(callback_id, "פותח מקורות וכתבים")
        send_control_menu("👥 מקורות וכתבים\nבחר פעולה.", _v27_sources_writers_markup(), message_id)
        return
    if data == "football_menu_teams_filter_v27":
        if callback_id:
            answer_control_callback(callback_id, "פותח קבוצות וסינון")
        send_control_menu("🛡️ קבוצות וסינון\nבחר פעולה.", _v27_teams_filter_markup(), message_id)
        return
    if data == "football_menu_reports_stats_v27":
        if callback_id:
            answer_control_callback(callback_id, "פותח דוחות וסטטיסטיקות")
        send_control_menu("📊 דוחות וסטטיסטיקות\nבחר פעולה.", _v27_reports_stats_markup(), message_id)
        return
    if data == "football_menu_system_memory_v27":
        if callback_id:
            answer_control_callback(callback_id, "פותח מערכת וזיכרון")
        send_control_menu("⚙️ מערכת וזיכרון\nבחר פעולה.", _v27_system_memory_markup(), message_id)
        return
    return _V27_PRE_PROCESS_CONTROL_UPDATE(update)


# ---------------------------------------------------------------------------
# 2) Telegram albums cannot reliably display inline markup on an album item.
#    For 2+ photos always create one compact reply message with Send/Delete.
#    This avoids the old false-positive edit result that left the album buttonless.
# ---------------------------------------------------------------------------
_V27_ALBUM_ACTION_LOCK = RLock()
_V27_ALBUM_ACTION_REPAIRING: set[str] = set()


def _v27_send_album_action_once(token: str, album_message_id: int) -> int:
    response = telegram_api(
        "sendMessage",
        {
            "chat_id": str(CONTROL_CHAT_ID),
            "text": "פעולות לדיווח:",
            "reply_to_message_id": int(album_message_id),
            "allow_sending_without_reply": True,
            "reply_markup": _v9_prepared_markup(token),
            "disable_web_page_preview": True,
        },
        max_attempts=1,
        timeout=max(8.0, REQUEST_TIMEOUT_SECONDS),
    )
    ids = [int(value) for value in _telegram_result_message_ids(response) if str(value).isdigit()]
    if not ids:
        raise RuntimeError("prepared_album_action_message_missing_id")
    action_id = ids[0]
    CONTROL_PREPARED_ACTION_CACHE[token] = action_id
    return action_id


def _v27_background_repair_album_actions(token: str, album_message_id: int) -> None:
    with _V27_ALBUM_ACTION_LOCK:
        if token in _V27_ALBUM_ACTION_REPAIRING:
            return
        _V27_ALBUM_ACTION_REPAIRING.add(token)

    def worker() -> None:
        try:
            for attempt in range(1, 13):
                try:
                    _v27_send_album_action_once(token, album_message_id)
                    logging.info(
                        "Prepared album action buttons recovered: token=%s album_message_id=%s attempt=%s",
                        token, album_message_id, attempt,
                    )
                    return
                except Exception as exc:
                    logging.warning(
                        "Prepared album action retry failed: token=%s attempt=%s error=%s",
                        token, attempt, short_error(exc, 300),
                    )
                    time.sleep(min(30.0, 2.0 + attempt * 2.0))
        finally:
            with _V27_ALBUM_ACTION_LOCK:
                _V27_ALBUM_ACTION_REPAIRING.discard(token)

    Thread(target=worker, daemon=True, name=f"album-actions-{token[:10]}").start()


def _user_v2_send_prepared_album_with_buttons(token: str, branded: list[str], message_html: str) -> list[int]:
    if not CONTROL_CHAT_ID or not branded:
        return []
    caption = _finalize_outgoing_message_only(message_html)
    if not _acceptance_caption_fits(caption):
        raise RuntimeError(hebrew_block_reason("caption_too_long_for_single_media_message"))

    markup = _v9_prepared_markup(token)
    response = _channel_send_photo_set_to_chat(
        str(CONTROL_CHAT_ID),
        branded,
        caption,
        reply_markup=markup if len(branded) == 1 else None,
    )
    ids = [int(value) for value in _telegram_result_message_ids(response) if str(value).isdigit()]
    if len(ids) != len(branded):
        _user_followup_delete_partial_control_messages(ids)
        raise RuntimeError(f"telegram_album_count_mismatch:{len(ids)}/{len(branded)}")

    _user_v6_delete_old_action_message(token)
    if len(ids) > 1:
        last_error: Exception | None = None
        for attempt, delay in enumerate((0.0, 0.6, 1.5, 3.0), 1):
            if delay:
                time.sleep(delay)
            try:
                _v27_send_album_action_once(token, ids[0])
                last_error = None
                break
            except Exception as exc:
                last_error = exc
                logging.warning(
                    "Prepared album action message attempt %s failed: %s",
                    attempt, short_error(exc, 350),
                )
        if last_error is not None:
            # Keep the successfully prepared album and continue retrying in the
            # background instead of deleting it or falsely claiming success.
            _v27_background_repair_album_actions(token, ids[0])
            logging.error(
                "Prepared album exists but action buttons are pending automatic recovery: token=%s error=%s",
                token, short_error(last_error, 400),
            )
    return ids


# ---------------------------------------------------------------------------
# 3) Translation safety: exact-source HERE WE GO only, conservative repair of
#    known literal Google phrases, and no false missing-number rejection for a
#    small number translated into Hebrew words or appearing only as metadata.
# ---------------------------------------------------------------------------
_V27_EXPLICIT_HWG_RE = re.compile(r"(?iu)(?<![A-Za-z])#?HERE(?:_|\s)+WE(?:_|\s)+GO\b")
_V27_OUTPUT_HWG_RE = re.compile(
    r"(?iu)(?:#?HERE(?:_|\s)+WE(?:_|\s)+GO\b|היר\s+וי\s+גו|הנה\s+זה\s+קורה|כאן\s+אנחנו\s+הולכים)"
)


def _v27_source_has_explicit_hwg(post: Post, quoted: bool = False) -> bool:
    return bool(_V27_EXPLICIT_HWG_RE.search(_final_corresponding_source_text(post, quoted=quoted)))


def _v27_repair_literal_transfer_translation(post: Post, value: Any, quoted: bool = False) -> str:
    text = str(value or "")
    source_has_hwg = _v27_source_has_explicit_hwg(post, quoted=quoted)

    # Exact known literal mistakes only; ordinary wording is untouched.
    text = re.sub(
        r"(?imu)^(?P<prefix>[ \t\u200e\u200f]*(?:[🚨🔵⚪️🔴🟡🟢🇧🇷🇩🇪🇮🇹🇪🇸🇫🇷]+[ \t]*)*)הבנת[ \t]+",
        lambda match: match.group("prefix") + "לפי המידע, ",
        text,
    )
    text = re.sub(r"(?iu)מהלך[ \t]+ההלוואה", "מהלך ההשאלה", text)
    text = re.sub(r"(?iu)עמלת[ \t]+הלוואה", "דמי השאלה", text)
    text = re.sub(r"(?iu)סעיף[ \t]+אופציית[ \t]+קנייה", "סעיף אופציית רכישה", text)
    text = re.sub(
        r"(?iu)(?:ה?פרטים[ \t]+האחרונים|פרטים[ \t]+אחרונים)[ \t]+(?:ממוינים|מסודרים)",
        "הפרטים האחרונים נמצאים בסגירה",
        text,
    )

    if source_has_hwg:
        text = re.sub(
            r"(?iu)הפרטים האחרונים נמצאים בסגירה[ \t]*(?:,|;|—|-)?[ \t]*(?:אז[ \t]+)?הנה[.!…]*",
            "הפרטים האחרונים נמצאים בסגירה, #HERE_WE_GO!",
            text,
        )
    else:
        text = _V27_OUTPUT_HWG_RE.sub("", text)
        text = re.sub(r"(?iu)(?:,|;|—|-)?[ \t]*(?:אז[ \t]+)?הנה[.!…]*", ".", text)

    text = re.sub(r"[ \t]+([,.;:!?])", r"\1", text)
    text = re.sub(r"([,;:])\s*([!?])", r"\2", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


_V27_PRE_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    translated = _v27_repair_literal_transfer_translation(post, translated, quoted=False)
    if quoted_translated:
        quoted_translated = _v27_repair_literal_transfer_translation(post, quoted_translated, quoted=True)
    rendered = _V27_PRE_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )

    combined_source = _final_corresponding_source_text(post, quoted=False)
    if quoted_translated:
        combined_source += "\n" + _final_corresponding_source_text(post, quoted=True)
    if not _V27_EXPLICIT_HWG_RE.search(combined_source):
        rendered = _V27_OUTPUT_HWG_RE.sub("", rendered)
        rendered = re.sub(r"[ \t]+([,.;:!?])", r"\1", rendered)
        rendered = re.sub(r"([,;:])\s*([!?])", r"\2", rendered)
        rendered = re.sub(r"[ \t]{2,}", " ", rendered)
        rendered = re.sub(r"\n{3,}", "\n\n", rendered)
    return rendered.strip()


_V27_SMALL_NUMBER_WORDS: dict[str, tuple[str, ...]] = {
    "0": ("אפס",),
    "1": ("אחד", "אחת", "שנה אחת",),
    "2": ("שניים", "שתיים", "שני", "שתי", "שנתיים",),
    "3": ("שלושה", "שלוש",),
    "4": ("ארבעה", "ארבע",),
    "5": ("חמישה", "חמש",),
    "6": ("שישה", "שש",),
    "7": ("שבעה", "שבע",),
    "8": ("שמונה",),
    "9": ("תשעה", "תשע",),
    "10": ("עשרה", "עשר",),
}
_V27_SINGLE_DIGIT_CONTEXT_RE = re.compile(
    r"(?iu)(?:€|£|\$|%|מיליון|אלף|אירו|דולר|פאונד|שנ(?:ה|ים|תיים)|חודש|ימים|"
    r"חוזה|משחקים|הופעות|שערים|בישולים|נקודות|מקום|דירוג|סעיף|אופציה|דמי|"
    r"million|thousand|euros?|dollars?|pounds?|years?|months?|days?|contract|"
    r"games?|appearances?|goals?|assists?|points?|option|fee|rank|number|no\.)"
)


def _v27_number_rendered_as_words(number: str, translated: str) -> bool:
    plain = html.unescape(re.sub(r"<[^>]+>", " ", str(translated or "")))
    for word in _V27_SMALL_NUMBER_WORDS.get(str(number), ()): 
        if re.search(rf"(?<![א-ת]){re.escape(word)}(?![א-ת])", plain):
            return True
    return False


def _v27_number_is_meaningful_in_source(number: str, source: str) -> bool:
    clean = URL_RE.sub(" ", str(source or ""))
    clean = BARE_EXTERNAL_DOMAIN_RE.sub(" ", clean)
    normalized = str(number or "").strip()
    if not normalized:
        return False
    if len(re.sub(r"\D", "", normalized)) >= 2 or "." in normalized:
        return normalized in _final_normalized_numbers(clean)
    for match in re.finditer(rf"(?<!\d){re.escape(normalized)}(?!\d)", clean):
        start = max(0, match.start() - 45)
        end = min(len(clean), match.end() + 45)
        context = clean[start:end]
        if _V27_SINGLE_DIGIT_CONTEXT_RE.search(context):
            return True
        if re.search(rf"\b\d+\s*[-:]\s*{re.escape(normalized)}\b|\b{re.escape(normalized)}\s*[-:]\s*\d+\b", context):
            return True
    return False


_V27_PRE_TRANSLATION_COMPLETENESS = _final_translation_completeness_issues


def _final_translation_completeness_issues(source: str, translated: str) -> list[str]:
    issues = list(_V27_PRE_TRANSLATION_COMPLETENESS(source, translated))
    result: list[str] = []
    for issue in issues:
        if not str(issue).startswith("חסרים מספרים מהמקור:"):
            result.append(issue)
            continue
        raw_numbers = str(issue).split(":", 1)[1]
        remaining: list[str] = []
        for number in [part.strip() for part in raw_numbers.split(",") if part.strip()]:
            if _v27_number_rendered_as_words(number, translated):
                continue
            if not _v27_number_is_meaningful_in_source(number, source):
                continue
            remaining.append(number)
        if remaining:
            result.append("חסרים מספרים מהמקור: " + ", ".join(remaining[:8]))
    return list(dict.fromkeys(result))


# ---------------------------------------------------------------------------
# 4) Recover an article-card image when X/RSS says a photo exists but only an
#    external webpage URL is available. Fetch only the small HTML page and use
#    og:image/twitter:image directly; no Pillow/logo/local re-encoding is used.
# ---------------------------------------------------------------------------
_V27_ARTICLE_IMAGE_CACHE_LOCK = RLock()
_V27_ARTICLE_IMAGE_CACHE: dict[str, tuple[float, str]] = {}
_V27_ARTICLE_IMAGE_CACHE_SECONDS = 6 * 60 * 60
_V27_ARTICLE_HTML_LIMIT = 2 * 1024 * 1024


def _v27_post_text_and_metadata_values(post: Post) -> list[str]:
    values: list[str] = []
    for name in (
        "original_text", "text", "original_quoted_text", "quoted_text", "raw_source_html",
        "rss_description", "description", "summary", "content", "card_url", "external_url",
        "expanded_url", "article_url", "source_url",
    ):
        value = getattr(post, name, "")
        if isinstance(value, str) and value.strip():
            values.append(html.unescape(value))
    for name in ("expanded_urls", "external_urls", "article_urls", "urls"):
        value = getattr(post, name, None)
        if isinstance(value, (list, tuple, set)):
            values.extend(str(item) for item in value if str(item).strip())
    return values


def _v27_external_article_urls(post: Post) -> list[str]:
    found: list[str] = []
    post_link = str(getattr(post, "link", "") or "").strip()
    for value in _v27_post_text_and_metadata_values(post):
        for raw in re.findall(r"https?://[^\s<>\"']+", value, flags=re.IGNORECASE):
            url = html.unescape(raw).rstrip(".,;:!?)]}>")
            if not url or url == post_link:
                continue
            try:
                host = urllib.parse.urlsplit(url).netloc.casefold()
            except Exception:
                host = ""
            if host.endswith(("x.com", "twitter.com", "nitter.net")):
                continue
            if any(url.casefold().endswith(ext) for ext in IMAGE_EXTENSIONS + VIDEO_EXTENSIONS):
                continue
            if url not in found:
                found.append(url)
    return found[:4]


def _v27_meta_image_from_html(raw_html: str, base_url: str) -> str:
    from html.parser import HTMLParser

    class PreviewParser(HTMLParser):
        def __init__(self) -> None:
            super().__init__(convert_charrefs=True)
            self.candidates: list[tuple[int, str]] = []

        def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
            data = {str(key or "").casefold(): str(value or "").strip() for key, value in attrs}
            if tag.casefold() == "meta":
                key = (data.get("property") or data.get("name") or data.get("itemprop") or "").casefold()
                content = data.get("content", "")
                priorities = {
                    "og:image:secure_url": 0,
                    "og:image": 1,
                    "twitter:image:src": 2,
                    "twitter:image": 3,
                    "image": 4,
                }
                if content and key in priorities:
                    self.candidates.append((priorities[key], content))
            elif tag.casefold() == "link":
                rel = data.get("rel", "").casefold()
                href = data.get("href", "")
                if href and "image_src" in rel:
                    self.candidates.append((5, href))

    parser = PreviewParser()
    try:
        parser.feed(raw_html)
    except Exception:
        pass
    for _priority, candidate in sorted(parser.candidates, key=lambda item: item[0]):
        absolute = urllib.parse.urljoin(base_url, html.unescape(candidate).strip())
        if absolute.startswith(("http://", "https://")):
            return absolute
    return ""


def _v27_fetch_article_preview_image(url: str) -> str:
    key = str(url or "").strip()
    if not key:
        return ""
    now = time.time()
    with _V27_ARTICLE_IMAGE_CACHE_LOCK:
        cached = _V27_ARTICLE_IMAGE_CACHE.get(key)
        if cached and now - cached[0] <= _V27_ARTICLE_IMAGE_CACHE_SECONDS:
            return cached[1]

    image_url = ""
    try:
        request = urllib.request.Request(
            key,
            headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/137.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
            },
        )
        with urllib.request.urlopen(request, timeout=6.0) as response:
            final_url = str(response.geturl() or key)
            content_type = str(response.headers.get("Content-Type") or "").casefold()
            body = response.read(_V27_ARTICLE_HTML_LIMIT + 1)
        if len(body) <= _V27_ARTICLE_HTML_LIMIT and ("html" in content_type or not content_type):
            decoded = body.decode("utf-8", errors="replace")
            image_url = _v27_meta_image_from_html(decoded, final_url)
    except Exception as exc:
        logging.debug("Article preview lookup failed safely for %s: %s", key, short_error(exc, 260))

    with _V27_ARTICLE_IMAGE_CACHE_LOCK:
        _V27_ARTICLE_IMAGE_CACHE[key] = (now, image_url)
    return image_url


def _v27_recover_external_article_image(post: Post) -> list[str]:
    existing = _final_dedupe_exact_photos(getattr(post, "external_preview_image_urls", []) or [])
    if existing:
        return existing[:MAX_IMAGES_PER_POST]

    tried: list[str] = []
    for article_url in _v27_external_article_urls(post):
        tried.append(article_url)
        image_url = _v27_fetch_article_preview_image(article_url)
        if not image_url:
            continue
        recovered = [image_url]
        post.external_preview_image_urls = recovered
        post.external_preview_article_url = article_url
        post.image_urls = _final_dedupe_exact_photos([
            *(getattr(post, "image_urls", []) or []),
            *recovered,
        ])
        post.exact_image_urls = list(post.image_urls)
        post.photo_expected = True
        logging.info(
            "Recovered external article preview image: post=%s article=%s image=%s",
            getattr(post, "post_id", ""), article_url, image_url,
        )
        return recovered
    post.external_preview_urls_tried = tried
    if tried:
        logging.warning(
            "External article preview image not found: post=%s urls_tried=%s",
            getattr(post, "post_id", ""), len(tried),
        )
    return []


_V27_PRE_HYDRATE_EXACT_POST = _reliable_hydrate_exact_post


def _reliable_hydrate_exact_post(post: Any, force: bool = False) -> Any:
    result = _V27_PRE_HYDRATE_EXACT_POST(post, force=force)
    if not isinstance(result, Post):
        return result
    has_images = bool(list(getattr(result, "image_urls", []) or []))
    should_try = bool(getattr(result, "photo_expected", False)) or bool(_v27_external_article_urls(result))
    if not has_images and should_try:
        try:
            _v27_recover_external_article_image(result)
        except Exception as exc:
            logging.warning(
                "External article image recovery failed safely for post %s: %s",
                getattr(result, "post_id", ""), short_error(exc, 320),
            )
    return result


_V27_PRE_SELECTED_POST_IMAGES = selected_post_images


def selected_post_images(post: Post) -> list[str]:
    _reliable_hydrate_exact_post(post)
    images = _final_dedupe_exact_photos(_V27_PRE_SELECTED_POST_IMAGES(post))
    if images:
        return images[:MAX_IMAGES_PER_POST]
    recovered = _final_dedupe_exact_photos(getattr(post, "external_preview_image_urls", []) or [])
    if not recovered:
        recovered = _v27_recover_external_article_image(post)
    return recovered[:MAX_IMAGES_PER_POST]


# V24 NBA/Instagram blocking is intentionally retained. V25 no-logo mode is also
# intentionally retained; this patch never restores image branding.
logging.info(
    "V27 active: grouped control menu, reliable album action reply, exact-source HERE_WE_GO, "
    "number-word validation and external article-card image fallback; RSS/logo mode unchanged"
)
# ====== END V27 CONTROL LAYOUT / RELIABLE ALBUM ACTIONS / SAFE TRANSLATION / ARTICLE-CARD IMAGE FALLBACK ======


# ====== V29 NARROW TEXT / SAME-EVENT DUPLICATE FIXES (2026-08-04) ======
# This layer intentionally changes only four user-requested behaviors:
# 1) remove the exact promotional sentence "the deal was completed by the agents...";
# 2) catch short paraphrases of the same transfer event;
# 3) allow the opening label "חדש:" to use the existing safe bold formatter;
# 4) remove stray pencil/period artifacts before the single Neto Sport footer.
# RSS, discovery cadence, media selection, server limits, buttons and persistence
# are deliberately untouched.

BOT_BUILD_ID = "winner-v29-agent-credit-same-event-new-label-punctuation-2026-08-04"

# "חדש:" is a one-word opening label, just like "דיווח:" and "רשמי:".
# The existing formatter still applies it only to the first report line and only
# when there is no reporter heading, so ordinary uses of the word חדש are untouched.
try:
    _V20_SAFE_OPENING_LABELS.add("חדש")
except Exception:
    pass


# ---------------------------------------------------------------------------
# 1) Remove only the exact agent-credit sentence requested by the user.
# Do not remove ordinary news about agents, representation, negotiations or any
# other sentence. The rule must start with "העסקה הושלמה..." and explicitly name
# the agent(s) as the people who completed it.
# ---------------------------------------------------------------------------
_V29_AGENT_COMPLETION_CREDIT_RE = re.compile(
    r"(?iu)(?<![A-Za-zא-ת0-9])"
    r"העסקה\s+הושלמה\s+(?:על\s+ידי|ע[\"״']?י)\s+"
    r"הסוכנ(?:ים|ות|ת)?\b[^.!?\n]{1,220}[.!?]?"
)
_V29_NON_SIGNATURE_PENCIL_RE = re.compile(r"(?iu)[ \t]*[.。]?[ \t]*📝[ \t]*$")
_V29_TRAILING_EMOJI_PERIOD_RE = re.compile(
    r"(?P<punct>[!?…])(?P<space>[ \t]*)"
    r"(?P<emoji>(?:[\U0001F1E6-\U0001F1FF\U0001F300-\U0001FAFF\u2300-\u27BF\ufe0f\u200d]+[ \t]*)+)"
    r"\.$"
)


def _v29_clean_requested_text_artifacts(value: Any) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    text = _V29_AGENT_COMPLETION_CREDIT_RE.sub("", text)

    cleaned_lines: list[str] = []
    for raw_line in text.split("\n"):
        line = raw_line.rstrip()
        visible = html.unescape(re.sub(r"<[^>]+>", "", line))
        is_neto_signature = bool(
            "t.me/neto_sport" in line
            or re.search(r"(?iu)נטו\s+ספורט", visible)
        )
        if not is_neto_signature:
            # A pencil belongs only to the canonical Neto Sport footer. Keep any
            # preceding flag/emoji, but remove the accidental ".📝" artifact.
            line = _V29_NON_SIGNATURE_PENCIL_RE.sub("", line).rstrip()
            # When a sentence already ends in !/?/… before its final emoji cluster,
            # a second full stop after the emoji is redundant: "! 🤍⏳." -> "! 🤍⏳".
            line = _V29_TRAILING_EMOJI_PERIOD_RE.sub(
                lambda match: match.group("punct") + match.group("space") + match.group("emoji").rstrip(),
                line,
            )

        line = re.sub(r"[ \t]+([.!?…])", r"\1", line)
        line = re.sub(r"\.{2,}", ".", line)
        line = re.sub(r"[ \t]{2,}", " ", line)
        cleaned_lines.append(line)

    text = "\n".join(cleaned_lines)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text


_V29_PRE_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    translated = _v29_clean_requested_text_artifacts(translated)
    if quoted_translated:
        quoted_translated = _v29_clean_requested_text_artifacts(quoted_translated)
    rendered = _V29_PRE_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    return _v29_clean_requested_text_artifacts(rendered)


_V29_PRE_FINALIZE_OUTGOING = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    return _v29_clean_requested_text_artifacts(_V29_PRE_FINALIZE_OUTGOING(message))


# ---------------------------------------------------------------------------
# 2) Conservative short-paraphrase duplicate rule for the same transfer event.
# It is intentionally directional: a later short summary is blocked when all of
# its named clubs were already present, the same distinctive identity is shared,
# and both reports are at the same transfer stage. A genuinely newer stage
# (interest -> agreement/official) is not blocked.
# ---------------------------------------------------------------------------
_V29_TRANSFER_CONTEXT_RE = re.compile(
    r"(?iu)(?:"
    r"transfer|move|sign(?:ing)?|join(?:ing)?|interest(?:ed)?|keen|candidate|"
    r"close(?:d|r)?|complete(?:d)?|agreement|deal|"
    r"העברה|מעבר|להחתים|יחתום|חתם|יצטרף|עניין|מעוניינ|מועמד|"
    r"צפוי\s+לה(?:יסגר|ושלם)|קרוב|הסכם|עסקה"
    r")"
)
_V29_INTEREST_STAGE_RE = re.compile(
    r"(?iu)(?:interest(?:ed)?|keen|monitoring|candidate|shortlist|considering|"
    r"מגלה\s+עניין|עניין\s+ב|מעוניינ|רשימת\s+המועמדים|ברשימת\s+המועמדים|בוחנת|שוקלת)"
)
_V29_CLOSE_STAGE_RE = re.compile(
    r"(?iu)(?:expected\s+to\s+(?:close|complete)|set\s+to\s+(?:close|complete)|"
    r"close\s+to|nearing|full\s+agreement\s+close|"
    r"צפוי\s+לה(?:יסגר|ושלם)|צפויה\s+לה(?:יסגר|ושלם)|"
    r"הסכם\s+מלא\s+קרוב|קרוב\s+ל(?:סגירה|השלמה)|צפוי\s+להיסגר\s+השבוע)"
)
_V29_OFFICIAL_STAGE_RE = re.compile(
    r"(?iu)(?:#?HERE(?:_|\s)+WE(?:_|\s)+GO|official|confirmed|deal\s+agreed|"
    r"agreement\s+reached|signed|completed|done\s+deal|medical(?:s)?\s+(?:booked|scheduled)|"
    r"רשמי|אושר|אושרה|העסקה\s+סוכמה|הושג\s+סיכום|חתם|נחתם|"
    r"העסקה\s+הושלמה|נקבעו\s+בדיקות|בדיקות\s+רפואיות)"
)


def _v29_transfer_stage(value: Any) -> int:
    text = str(value or "")
    if _V29_OFFICIAL_STAGE_RE.search(text):
        return 3
    if _V29_CLOSE_STAGE_RE.search(text):
        return 2
    if _V29_INTEREST_STAGE_RE.search(text):
        return 1
    return 0


def _v29_conservative_same_transfer_event(current_text: str, previous_text: str) -> bool:
    if not _V29_TRANSFER_CONTEXT_RE.search(current_text) or not _V29_TRANSFER_CONTEXT_RE.search(previous_text):
        return False

    current_stage = _v29_transfer_stage(current_text)
    previous_stage = _v29_transfer_stage(previous_text)
    if current_stage <= 0 or previous_stage <= 0:
        return False
    # A current report that materially advances the event must remain publishable.
    if current_stage > previous_stage:
        return False

    try:
        current_teams = set(_final_logical_team_ids(current_text) or set())
        previous_teams = set(_final_logical_team_ids(previous_text) or set())
    except Exception:
        return False
    if not current_teams or not previous_teams:
        return False
    # The later short version may omit a contextual club (e.g. another interested
    # club mentioned only in the longer report), but it may not introduce a new club.
    if current_teams - previous_teams:
        return False

    try:
        shared_identity = set(_final_event_identity_tokens(current_text) or set()) & set(
            _final_event_identity_tokens(previous_text) or set()
        )
    except Exception:
        shared_identity = set()
    # Require multiple shared distinctive tokens and at least one long token.
    # This catches the supplied Reijnders/Diomande examples while avoiding a
    # same-club match based only on generic words such as "השבוע" or "מעבר".
    if len(shared_identity) < 2 or not any(len(token) >= 7 for token in shared_identity):
        return False
    return True


_V29_PRE_V9_SAME_EVENT_TEXT = _v9_same_event_text


def _v9_same_event_text(current_text: str, previous_text: str) -> tuple[bool, float]:
    same, score = _V29_PRE_V9_SAME_EVENT_TEXT(current_text, previous_text)
    if same:
        return same, score
    if _v29_conservative_same_transfer_event(current_text, previous_text):
        return True, max(float(score or 0.0), 0.96)
    return False, score


logging.info(
    "V29 active: exact agent-credit removal, conservative same-transfer duplicate catch, "
    "bold חדש opener and punctuation cleanup; RSS/server/button settings unchanged"
)
# ====== END V29 NARROW TEXT / SAME-EVENT DUPLICATE FIXES ======


# ====== V30 EXACT WRITER SPACING / SINGLE FOOTER / OPENING-LABEL LINE BREAK ======
# Narrow formatting-only patch requested on 2026-08-04:
# - exactly one empty line between a reporter heading and the report;
# - exactly one canonical Neto Sport footer, even when a legacy footer was glued
#   to a flag/emoji line;
# - after a bold opening label such as "פרסום ראשון:", place the report on the
#   immediately following line (no empty line);
# - remove redundant full stops around trailing emoji clusters.
# RSS, discovery, filters, buttons, media, server limits and persistence are untouched.

BOT_BUILD_ID = "winner-v30-writer-spacing-single-footer-opening-line-2026-08-04"

_V30_INVISIBLE_CHARS = "\u200e\u200f\u202a\u202b\u202c\u202d\u202e\u2066\u2067\u2068\u2069\ufeff"
_V30_EMOJI_BASE = r"[\U0001F1E6-\U0001F1FF\U0001F300-\U0001FAFF\u2300-\u27BF]"
_V30_EMOJI_CLUSTER = rf"(?:{_V30_EMOJI_BASE}(?:\ufe0f|\u200d{_V30_EMOJI_BASE})*)"

_V30_SIGNATURE_PATTERNS = (
    re.compile(
        r'(?is)[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*'
        r'<a\s+[^>]*href=["\']https?://t\.me/neto_sport/?["\'][^>]*>'
        r'\s*[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*נטו\s+ספורט\s*'
        r'</a>\s*[.。]?\s*📝'
    ),
    re.compile(
        r'(?is)[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*'
        r'\[\s*נטו\s+ספורט\s*\]\(\s*https?://t\.me/neto_sport/?\s*\)\s*[.。]?\s*📝'
    ),
    re.compile(
        r'(?is)[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*'
        r'נטו\s+ספורט\s*\(\s*https?://t\.me/neto_sport/?\s*\)\s*[.。]?\s*📝'
    ),
    re.compile(
        r'(?is)[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*'
        r'נטו\s+ספורט\s*[.。]?\s*📝'
    ),
)


def _v30_visible_line(value: Any) -> str:
    return html.unescape(re.sub(r"<[^>]+>", "", str(value or ""))).strip(
        " \t" + _V30_INVISIBLE_CHARS
    )


def _v30_known_writer_labels() -> set[str]:
    labels: set[str] = set()
    for value in ACCOUNT_DISPLAY_NAMES.values():
        clean = str(value or "").strip().rstrip(":").strip()
        if clean:
            labels.add(clean.casefold())
    labels.update({
        "פבריציו רומאנו מאשר",
    })
    return labels


_V30_WRITER_LABELS = _v30_known_writer_labels()


def _v30_is_writer_heading(line: str) -> bool:
    visible = _v30_visible_line(line)
    if not visible.endswith(":"):
        return False
    label = visible[:-1].strip().casefold()
    if label in _V30_WRITER_LABELS:
        return True
    # A bold opening label such as "פרסום ראשון:" is not a reporter heading.
    # For an unknown dynamically configured reporter, accept the heading only
    # when it has no leading emoji and is not one of the safe opening labels.
    safe_labels = {str(item).casefold() for item in _V20_SAFE_OPENING_LABELS}
    has_leading_emoji = bool(re.match(
        rf"^[{re.escape(_V30_INVISIBLE_CHARS)} \t]*(?:{_V30_EMOJI_CLUSTER})",
        line,
    ))
    return bool(
        re.search(r"<(?:b|strong)\b", line, re.I)
        and 2 <= len(label) <= 60
        and label not in safe_labels
        and not has_leading_emoji
    )


def _v30_split_inline_writer_heading(value: Any) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    first = next((idx for idx, line in enumerate(lines) if line.strip()), None)
    if first is None:
        return text
    line = lines[first]
    match = re.match(
        rf"^(?P<prefix>[{re.escape(_V30_INVISIBLE_CHARS)} \t]*)"
        r"(?P<head><(?P<tag>b|strong)(?:\s+[^>]*)?>.*?:\s*</(?P=tag)>)"
        r"[ \t]+(?P<body>\S.*)$",
        line,
        re.I,
    )
    if not match or not _v30_is_writer_heading(match.group("head")):
        return text
    body = match.group("body").lstrip()
    if re.search(r"[\u0590-\u05FF]", _v30_visible_line(body)) and not body.lstrip().startswith(RTL_MARK):
        body = RTL_MARK + body
    lines[first:first + 1] = [match.group("prefix") + match.group("head"), "", body]
    return "\n".join(lines)


def _v30_remove_all_neto_footers(value: Any) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    for pattern in _V30_SIGNATURE_PATTERNS:
        text = pattern.sub("", text)
    # Remove an orphan pencil left by a legacy signature only when it is its own
    # trailing artifact. Other pencil emoji inside a report are untouched.
    text = re.sub(
        r"(?im)^[ \t\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*[.。]?[ \t]*📝[ \t]*$",
        "",
        text,
    )
    return text


def _v30_clean_emoji_punctuation(value: Any) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    cleaned: list[str] = []
    for raw_line in text.split("\n"):
        line = raw_line.rstrip()
        # Keep a normal sentence-ending mark before the emoji, but ensure a
        # readable space: "קבועות.🧤" -> "קבועות. 🧤".
        line = re.sub(
            rf"([.!?…])(?={_V30_EMOJI_CLUSTER})",
            r"\1 ",
            line,
        )
        # A full stop after an emoji is redundant when another emoji follows or
        # when the emoji cluster is already the visual end of the line.
        line = re.sub(
            rf"(?P<emoji>{_V30_EMOJI_CLUSTER})[ \t]*\.(?=[ \t]*(?:{_V30_EMOJI_CLUSTER}|$))",
            lambda match: match.group("emoji"),
            line,
        )
        line = re.sub(r"[ \t]+([.!?…])", r"\1", line)
        line = re.sub(r"\.{2,}", ".", line)
        line = re.sub(r"[ \t]{2,}", " ", line)
        cleaned.append(line)
    return "\n".join(cleaned)


def _v30_split_bold_opening_label(value: Any) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    nonempty = [idx for idx, line in enumerate(lines) if line.strip()]
    if not nonempty:
        return text

    report_index = nonempty[0]
    if _v30_is_writer_heading(lines[report_index]):
        for idx in nonempty[1:]:
            report_index = idx
            break
        else:
            return text

    line = lines[report_index]
    labels = sorted((str(item) for item in _V20_SAFE_OPENING_LABELS), key=len, reverse=True)
    label_alt = "|".join(re.escape(item) for item in labels)
    pattern = re.compile(
        rf"^(?P<prefix>[{re.escape(_V30_INVISIBLE_CHARS)} \t]*)"
        rf"(?P<emoji>(?:{_V30_EMOJI_CLUSTER}[ \t]*)*)"
        rf"(?P<bold><(?P<tag>b|strong)(?:\s+[^>]*)?>\s*(?:{label_alt})\s*:\s*</(?P=tag)>)"
        r"[ \t]*(?P<body>\S.*)$",
        re.I,
    )
    match = pattern.match(line)
    if not match:
        # Also accept Telegram-style Markdown cached in an old prepared message.
        markdown_pattern = re.compile(
            rf"^(?P<prefix>[{re.escape(_V30_INVISIBLE_CHARS)} \t]*)"
            rf"(?P<emoji>(?:{_V30_EMOJI_CLUSTER}[ \t]*)*)"
            rf"(?P<bold>\*\*\s*(?:{label_alt})\s*:\s*\*\*)"
            r"[ \t]*(?P<body>\S.*)$",
            re.I,
        )
        match = markdown_pattern.match(line)
    if not match:
        return text

    opening_line = (match.group("prefix") + match.group("emoji") + match.group("bold")).rstrip()
    body_line = match.group("body").lstrip()
    if re.search(r"[\u0590-\u05FF]", _v30_visible_line(body_line)) and not body_line.lstrip().startswith(RTL_MARK):
        body_line = RTL_MARK + body_line
    lines[report_index:report_index + 1] = [opening_line, body_line]
    return "\n".join(lines)


def _v30_strip_same_writer_prefix(line: str, writer_label: str) -> tuple[str, bool]:
    variants = {
        writer_label,
        html.escape(writer_label, quote=False),
        html.escape(writer_label, quote=True),
    }
    variants = {item for item in variants if item}
    if not variants:
        return line, False
    alt = "|".join(re.escape(item) for item in sorted(variants, key=len, reverse=True))
    pattern = re.compile(
        rf"^[{re.escape(_V30_INVISIBLE_CHARS)} \t]*"
        r"(?:<(?:b|strong)(?:\s+[^>]*)?>\s*)?"
        rf"[{re.escape(_V30_INVISIBLE_CHARS)} \t]*(?:{alt})\s*:"
        r"\s*(?:</(?:b|strong)>\s*)?",
        re.I,
    )
    match = pattern.match(line)
    if not match:
        return line, False
    return line[match.end():].lstrip(" \t" + _V30_INVISIBLE_CHARS), True


def _v30_force_writer_paragraph_gap(value: Any) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    first = next((idx for idx, line in enumerate(lines) if line.strip()), None)
    if first is None or not _v30_is_writer_heading(lines[first]):
        return text
    writer_label = _v30_visible_line(lines[first])[:-1].strip()

    # Remove only repeated copies of the same writer immediately after the
    # canonical first heading. A mention later in the report is never touched.
    cursor = first + 1
    while cursor < len(lines):
        if not lines[cursor].strip():
            cursor += 1
            continue
        stripped, changed = _v30_strip_same_writer_prefix(lines[cursor], writer_label)
        if not changed:
            break
        if stripped:
            if re.search(r"[\u0590-\u05FF]", _v30_visible_line(stripped)) and not stripped.lstrip().startswith(RTL_MARK):
                stripped = RTL_MARK + stripped
            lines[cursor] = stripped
            break
        del lines[cursor]

    body = next((idx for idx in range(first + 1, len(lines)) if lines[idx].strip()), None)
    if body is None:
        return "\n".join(lines[:first + 1])
    # Remove any existing blank-line count and insert exactly one empty line.
    return "\n".join(lines[:first + 1] + [""] + lines[body:])


def _v30_format_report_body(value: Any) -> str:
    text = _v30_remove_all_neto_footers(value)
    text = _v30_clean_emoji_punctuation(text)
    text = _v30_split_inline_writer_heading(text)
    text = _v30_split_bold_opening_label(text)
    text = _v30_force_writer_paragraph_gap(text)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text


_V30_PRE_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _V30_PRE_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    return _v30_format_report_body(rendered)


_V30_PRE_FINALIZE_OUTGOING = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    # Let the existing chain perform all established sanitizing first, then make
    # the final Telegram payload deterministic at the absolute boundary.
    rendered = _V30_PRE_FINALIZE_OUTGOING(message)
    body = _v30_format_report_body(rendered)
    signature = RTL_MARK + f'<a href="{html.escape(SIGNATURE_LINK, quote=True)}">נטו ספורט</a>.📝'
    return (body + "\n\n" + signature).strip() if body else signature


logging.info(
    "V30 active: exact writer paragraph gap, one Neto footer, opening label on its own line, "
    "and trailing emoji punctuation cleanup; RSS/buttons/server settings unchanged"
)
# ====== END V30 EXACT WRITER SPACING / SINGLE FOOTER / OPENING-LABEL LINE BREAK ======


# ====== V31 EXACTLY ONE NETO SPORT FOOTER AT EVERY REPORT SEND BOUNDARY ======
# Formatting-only hardening requested on 2026-08-04. V30 correctly normalized
# the footer whenever its finalizer was called, but several established media
# routes (especially original-photo/album sends after V25) could hand a caption
# directly to Telegram without passing through that finalizer. Text routes did
# pass through it, which explains why the footer appeared on some reports but
# was missing on others. Make the operation idempotent and apply it at each
# actual report-delivery boundary. RSS, discovery, buttons, filters, translation,
# media selection, server limits and persistence are unchanged.

BOT_BUILD_ID = "winner-v31-exact-one-footer-all-report-routes-2026-08-04"

_V31_SIGNATURE_HTML = (
    RTL_MARK
    + f'<a href="{html.escape(SIGNATURE_LINK, quote=True)}">נטו ספורט</a>.📝'
)


def _v31_exact_single_neto_footer(value: Any) -> str:
    """Return the report with one canonical footer, regardless of input state.

    `_v30_format_report_body` removes every supported old/HTML/Markdown/plain
    Neto Sport footer, including a footer glued to a flag line. Appending the
    canonical footer afterwards makes this function safe to call repeatedly.
    """
    body = _v30_format_report_body(value)
    return (body + "\n\n" + _V31_SIGNATURE_HTML).strip() if body else _V31_SIGNATURE_HTML


# Use the deterministic implementation directly rather than passing through the
# historical chain of finalizers. Every existing caller that resolves this name
# dynamically now receives the same exactly-once behavior.
_finalize_outgoing_message_only = _v31_exact_single_neto_footer


# Main-channel JSON broadcasts are a final boundary for older text/media routes.
# Only HTML report fields are normalized; startup/status payloads without HTML
# parse mode remain untouched.
_V31_PRE_TELEGRAM_BROADCAST = telegram_broadcast


def telegram_broadcast(
    method: str,
    payload: dict[str, Any],
    reply_message_ids: dict[str, int] | None = None,
) -> dict[str, int]:
    clean_payload = dict(payload or {})
    parse_mode = str(clean_payload.get("parse_mode") or "").upper()
    if parse_mode == "HTML":
        if "text" in clean_payload:
            clean_payload["text"] = _v31_exact_single_neto_footer(clean_payload["text"])
        if "caption" in clean_payload:
            clean_payload["caption"] = _v31_exact_single_neto_footer(clean_payload["caption"])

    if isinstance(clean_payload.get("media"), list):
        media: list[Any] = []
        for raw_item in clean_payload["media"]:
            if not isinstance(raw_item, dict):
                media.append(raw_item)
                continue
            item = dict(raw_item)
            if str(item.get("parse_mode") or "").upper() == "HTML" and "caption" in item:
                item["caption"] = _v31_exact_single_neto_footer(item["caption"])
            media.append(item)
        clean_payload["media"] = media

    return _V31_PRE_TELEGRAM_BROADCAST(
        method,
        clean_payload,
        reply_message_ids=reply_message_ids,
    )


# V25's no-logo sender is the absolute boundary for original photos and albums,
# both in the quiet channel and in the main channel. It previously accepted a
# caption that was not guaranteed to have passed through the finalizer.
_V31_PRE_ORIGINAL_PHOTO_SET_SENDER = _v25_send_original_photo_set_to_chat


def _v25_send_original_photo_set_to_chat(
    chat_id: str,
    images: list[str],
    caption: str,
    reply_markup: dict[str, Any] | None = None,
    reply_id: int | None = None,
) -> dict[str, Any]:
    return _V31_PRE_ORIGINAL_PHOTO_SET_SENDER(
        str(chat_id),
        images,
        _v31_exact_single_neto_footer(caption),
        reply_markup=reply_markup,
        reply_id=reply_id,
    )


# Keep both dynamically resolved names on the same corrected photo boundary.
_channel_send_photo_set_to_chat = _v25_send_original_photo_set_to_chat


# Video captions use a separate direct Telegram path, so normalize them at that
# boundary as well. A video sent without a caption remains unchanged.
