    if _V37_TROLL_ENGAGEMENT_BAIT_RE.search(text):
        return "trollfootball_engagement_or_hatewatch_noise"
    if _V37_TROLL_LIVE_TABLE_RE.search(text):
        return "trollfootball_live_score_or_table_update"
