def _v56_rss_path_text(username: str) -> str:
    with _V56_MANUAL_RSS_DIAGNOSTICS_LOCK:
        diagnostics = dict(_V56_MANUAL_RSS_DIAGNOSTICS.get(str(username or "").casefold(), {}))
