SOURCE_REPORT_MIN_WORDS = 12
FOOTBALL_FACTLY_MIN_WORDS = SOURCE_REPORT_MIN_WORDS
FOOTBALL_FACTLY_AUTO_MIN_WORDS = SOURCE_REPORT_MIN_WORDS
OPTAJOE_AUTO_MIN_WORDS = SOURCE_REPORT_MIN_WORDS
