def hebrew_block_reason(reason: str) -> str:
    raw = str(reason or "")
    if "trollfootball_future_match_prediction" in raw:
        return "טרול פוטבול: תחזית עתידית על שערים/תוצאה/מנצחת היא תוכן הימורי ולא דיווח"
